var ZLEARN_QUESTION_CATALOG = [{"question":{"id":"fq1-q01","type":"recall","phase":"pretest","prompt":"ما اسم المنظومة؟ ومن ناظمها؟","answer":"«المرشد المعين على الضروري من علوم الدين»، وناظمها الشيخ العلامة عبد الواحد ابن عاشر الأنصاري الفاسي.","explain":"تجد الجواب في «بطاقة التعريف» أول الدرس: المنظومة عنوانها «المرشد المعين على الضروري من علوم الدين»، وناظمها عبد الواحد ابن عاشر الأنصاري الفاسي المتوفى سنة 1040هـ، وقد افتتح أبياته بقوله: «يقولُ عبدُ الواحدِ ابنُ عاشرِ».","section":"identity","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q02","type":"recall","phase":"pretest","prompt":"ما الكتاب المعتمد في شرحها؟ ومن مؤلفه؟","answer":"«الحبل المتين»، ومؤلفه الشيخ محمد بن محمد بن عبد الله ابن المبارك، المعروف بابن المؤقت المراكشي.","explain":"الشرح المعتمد في المادة هو «الحبل المتين» لابن المؤقت المراكشي (ت 1396هـ)، وهو الذي يُقرأ في الدرس. لا تخلط بين الناظم صاحب المتن، وهو ابن عاشر، وبين الشارح، وهو ابن المؤقت؛ فقد جمعت المادة بين المتن وشرحه.","section":"identity","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q03","type":"recall","phase":"practice","prompt":"على أي بحر نُظمت المنظومة؟ وما وزنه؟","answer":"على بحر الرجز، ووزنه «مستفعلن» ست مرات.","explain":"وزن المتن مذكور في «بطاقة التعريف»: نُظم على بحر الرجز، ووزنه «مستفعلن» ست مرات. ومعرفة البحر تعينك على القراءة الصحيحة والإلقاء، لأن المنظومة كلها على هذا الوزن الواحد؛ «مستفعلن» تكرر ست مرات في البيت.","section":"identity","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q04","type":"recall","phase":"practice","prompt":"كم قسمًا للمنظومة؟ وما صلتها بحديث جبريل؟","answer":"ثلاثة أقسام على ترتيب الحديث: الإيمان (العقيدة)، والإسلام (الفقه)، والإحسان (التصوف والأخلاق).","explain":"قسّم الناظم متنه ثلاثة أقسام على ترتيب أسئلة جبريل عليه السلام حين سأل النبي ﷺ عن الإيمان والإسلام والإحسان، وهذا الترتيب هو ضابطٌ يحفظ لك الأقسام: العقيدة أولًا لأنها الأصل، ثم الفقه لأنها العمل، ثم التصوف لأنه إحسان. وقد لخّصها في البيت الثالث: «في عقدِ الأشعريِّ وفقهِ مالكِ / وفي طريقةِ الجنيدِ السالكِ».","section":"parts","checkpoint":"parts","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q05","type":"recall","phase":"practice","prompt":"على أي مذهب أو طريقة بُني كل قسم؟","answer":"العقيدة على مذهب أبي الحسن الأشعري، والفقه على مذهب الإمام مالك بن أنس، والتصوف على طريقة الإمام الجنيد السالك.","explain":"ذكر الناظم إمام كل قسم في البيت: «في عقدِ الأشعريِّ وفقهِ مالكِ / وفي طريقةِ الجنيدِ السالكِ»، فالعقيدة تُؤخذ على مذهب أبي الحسن الأشعري، والفقه على مذهب مالك بن أنس، والتصوف على طريقة الجنيد. فالمتن يجمع بين ثلاث مدارس على ترتيب الحديث.","section":"parts","checkpoint":"parts","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q06","type":"recall","phase":"practice","prompt":"اذكر ترتيب خطبة المنظومة.","answer":"التعريف بالنفس، البسملة، الحمدلة، الصلاة على النبي ﷺ، «وبعد»، ثم الاستعانة وبيان الغرض.","explain":"المقدمة تسير على هذا الترتيب بلا تقديم ولا تأخير، وقد شرح الأستاذ معنى كل خطوة: البسملة تيمّنًا، والحمدلة عملًا بحديث «كل أمر ذي بال لا يُبدأ فيه بالحمد لله فهو أقطع»، ثم الصلاة على النبي ﷺ، ثم «وبعد» للانتقال من المقدمة إلى المقصود، ثم الاستعانة وبيان الغرض. فاحفظ الخطوات كما هي لأن بعضها يبنى على بعض.","section":"khutba","checkpoint":"khutba","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q07","type":"recall","phase":"practice","prompt":"لماذا عرّف الناظم بنفسه في أول المنظومة؟","answer":"لتُعرف نسبة المنظومة إلى صاحبها، لأن هذا العلم دين فيجب النظر عمّن نأخذه، كما قال ابن سيرين.","explain":"التعريف بالنفس ليس زيادة، بل ضمانٌ لنسبة المتن إلى صاحبه حتى لا يُنسب لغيره. وقد استشهد الأستاذ بقول ابن سيرين: «إن هذا العلم دين فانظروا عمّن تأخذون دينكم»، فالمقصود أن تعرف عمّن تأخذ العلم؛ وهذا هو «الأصل في ذلك» الذي أورده الدرس في خطوة التعريف.","section":"khutba","checkpoint":"khutba","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q08","type":"recall","phase":"practice","prompt":"ما معنى «أقطع» و«أبتر» في الحديث؟ وما حكم الصلاة على النبي ﷺ؟","answer":"معناهما: منزوع البركة. والصلاة على النبي ﷺ واجبة مرة في العمر.","explain":"«أقطع» و«أبتر» بمعنى واحد: منزوع البركة، وهو وصف كل أمر ذي بال لا يُبدأ بالحمد لله؛ ولهذا افتتح الناظم بالحمدلة. وأما الصلاة على النبي ﷺ فقد جاءت في الخطبة بعد البسملة والحمدلة، وحكمها أنها واجبة مرة في العمر، وجمع معها الآل والصحب ومن اقتدى بهم.","section":"khutba","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q09","type":"recall","phase":"practice","prompt":"ما معنى «الأمّي» في قول الناظم؟ ولماذا نُقلت حركة الهمزة؟","answer":"هو المبتدئ: المنسوب إلى الأمة الأمية، أو إلى الأمّ أي باقٍ على حاله الأول من خلو الذهن. ونُقلت حركة الهمزة إلى الساكن الصحيح قبلها لاستقامة الوزن.","explain":"في «مصطلحات الدرس» أن «الأمّي» يقال للمنسوب إلى الأمة الأمية، كما في الحديث: «نحن أمة أمية لا نكتب ولا نحسب»، أو للمنسوب إلى الأمّ أي الباقي على حاله عند الولادة من خلو الذهن من العلوم المكتسبة؛ والمراد به هنا المبتدئ. وأما نقل حركة الهمزة إلى الساكن الصحيح قبلها فسببه إصلاح الوزن حتى يستقيم البيت.","section":"terms","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q10","type":"recall","phase":"practice","prompt":"ما المقرر في السنة الأولى والثانية؟ وما حكم تعلم مسائله؟","answer":"قسم الفقه من المنظومة. وأحكام العبادات يجب على المسلم أن يتعلمها، ولا يُعذر بجهله إن جهل منها مسألة واحدة.","explain":"في بيان أقسام المنظومة عند قسم الفقه أن مسائله هي مقرر السنة الأولى والسنة الثانية، وهو أحكام العبادات: الطهارة والصلاة والزكاة والصيام والحج. وسبب تعيينه أن هذه الأحكام يجب على المسلم تعلمها، ولا يُعذر بجهله إذا جهل منها مسألة واحدة، بخلاف ما لو كان العلم تطوعًا.","section":"parts","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q12","type":"recall","phase":"practice","prompt":"كيف ترتبط أقسام منظومة ابن عاشر الثلاثة بحديث جبريل عليه السلام؟","answer":"أن الأقسام الثلاثة جاءت على ترتيب حديث جبريل: الإيمان يقابل العقيدة، والإسلام يقابل الفقه، والإحسان يقابل التصوف.","explain":"قسّم ابن عاشر منظومته على ما جاء في حديث جبريل حين سأل النبي ﷺ عن الإيمان والإسلام والإحسان، فجاء قسم العقيدة للإيمان، وقسم الفقه للإسلام، وقسم التصوف للإحسان.","section":"parts","difficulty":2},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq1-q13","type":"cloze","phase":"practice","prompt":"أكمل ترتيب خطبة المنظومة كما ورد في الدرس: التعريف بالنفس، ثم البسملة، ثم الحمدلة، ثم ______، ثم «وبعد»، ثم الاستعانة وبيان الغرض.","answer":"الصلاة والسلام على النبي ﷺ","explain":"الصلاة والسلام على النبي ﷺ جاءت ثالثة بعد البسملة والحمدلة، وهي واجبة مرة في العمر.","section":"khutba","difficulty":2},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"مقدمة المنظومة","url":"fiqh/01-lesson/index.html"},{"question":{"id":"fq2-q01","type":"recall","phase":"pretest","prompt":"لماذا قدّم ابن عاشر هذه المقدمة قبل أبواب الفقه؟","answer":"ليعرّف بالمصطلحات والألفاظ التي ستتكرر في كل باب. مثال: صيام رمضان فرض، وصوم رجب وشعبان مندوب، فلا بد من معرفة معنى الفرض والمندوب.","explain":"قدّم ابن عاشر المقدمة ليقيم ميزانًا للمصطلحات قبل الدخول في أبواب الفقه، لأن ألفاظًا كالفرض والمندوب تتكرر في كل باب. وأوضح مثال في الخلاصة: صيام رمضان من الفرض، وصوم رجب وشعبان من المندوب؛ فمن لم ينضبط عنده المعنى اختلط عليه الحكم.","section":"l2-summary","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q02","type":"recall","phase":"pretest","prompt":"ما أقسام الحكم الشرعي؟","answer":"خمسة: الفرض، والمندوب، والمكروه، والحرام، والمباح.","explain":"جعلها الدرس خمسة لأن التقسيم مبنيّ على ملاحظتين: وجه الطلب وجزمه. وقد لخّص الناظم القسمة في بيته: «أقسامُ حكمِ الشرعِ خمسةٌ تُرامْ / فرضٌ وندبٌ وكراهةٌ حرامْ»، ثم أتمّها بالمكروه والمباح؛ فرتّب المخطط الفرض والمندوب في طلب الفعل، والحرام والمكروه في طلب الترك، والمباح في الإذن.","section":"l2-tree","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q03","type":"recall","phase":"practice","prompt":"عرّف الفرض والمندوب.","answer":"الفرض ما طلب الشارع فعله طلبًا جازمًا. والمندوب ما طلب الشارع فعله طلبًا غير جازم.","explain":"كليهما مطلوب الفعل، لكن الفرض واقع تحت الأمر الجازم الذي لا يسمح الشارع بتركه فيُعاقب تاركه، والمندوب دون ذلك الجزم فلا عقاب على تركه. وفي الجدول أن الفرض من قواعد الإسلام عمومًا، ومن أمثلة المندوب ركعتا الفجر.","section":"l2-table","checkpoint":"l2-table","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q04","type":"recall","phase":"practice","prompt":"عرّف المكروه والحرام.","answer":"المكروه ما طلب الشارع تركه طلبًا غير جازم. والحرام ما طلب الشارع تركه طلبًا جازمًا.","explain":"كلاهما نهي عن الفعل، ويفترقان بقوة النهي: فالحرام نهي جازم لم يُجوّز الشارع فيه الفعل فيُعاقب فاعله، والمكروه نهي غير جازم جُوّز فيه الفعل فلا عقاب على فاعله. وقد مثّل الجدول للحرام بشرب الخمر، وللمكروه بالقراءة في الركوع والسجود.","section":"l2-table","checkpoint":"l2-table","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q05","type":"recall","phase":"practice","prompt":"ما المباح؟","answer":"ما أذن الشارع في فعله وتركه، أي تساوى فيه الفعل والترك.","explain":"هو القسم الذي لا أمر فيه ولا نهي، بل أذن الشارع في الفعل والترك على حدّ سواء؛ ولهذا وصفه الناظم بأنه «مأذونُ وجهيهِ»، وسمّاه المخطط «تخييرًا». فلا ثواب على فعله ولا عقاب على تركه، ولهذا لم يذكر له الدرس مثالًا.","section":"l2-table","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q06","type":"recall","phase":"practice","prompt":"ما الذي يترتب على كل حكم من الأحكام الخمسة؟","answer":"الفرض: يُثاب فاعله ويُعاقب تاركه. المندوب: يُثاب فاعله ولا يُعاقب تاركه. الحرام: يُعاقب فاعله ويُثاب تاركه. المكروه: لا يُعاقب فاعله ويُثاب تاركه. المباح: لا ثواب ولا عقاب.","explain":"الجزاء تابع لجزم الطلب: فما كان طلبه جازمًا لزمه العقاب عند المخالفة، وما كان غير جازم فلا إثم في مخالفته. ولهذا يُثاب فاعل الفرض وتارك الحرام، ولا يُعاقب تارك المندوب ولا فاعل المكروه. أما المباح فتساوى فيه الطرفان فسقط عنه الثواب والعقاب معًا.","section":"l2-tree","checkpoint":"l2-tree","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q07","type":"recall","phase":"practice","prompt":"من هو الشارع؟","answer":"الله سبحانه وتعالى، وهو المشرّع. ويُقال: الرسول ﷺ نيابة عن الله أو بوحي منه.","explain":"في مصطلحات الدرس أن الشارع هو الله سبحانه وهو المشرّع، فإن أُسند التشريع إلى الرسول ﷺ فبحسب النيابة عن الله أو الوحي لا بحسب الاستقلال. وهذا المصطلح أصل لبقية التعريفات؛ إذ كل الأحكام منسوبة إلى طلب الشارع.","section":"l2-terms","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q08","type":"recall","phase":"practice","prompt":"ما أقسام الفرض؟ مثّل لكل قسم.","answer":"فرض عين: يتعين على كل مكلف بعينه، كالصلوات الخمس. وفرض كفاية: إذا قام به البعض سقط الإثم عن الباقين، كإمامة الناس في الصلاة وشهادة القاضي والأمر بالمعروف والنهي عن المنكر.","explain":"الفرق بين قسمي الفرض فيمن يتعيّن عليه الفعل: فالعيني لزم كل مكلف بعينه كالصلوات الخمس، والكفائي يكفي فيه قيام البعض فيسقط الإثم عن الباقين. ومن أمثلة الكفائي في المخطط إمامة الناس في الصلاة، وشهادة القاضي، والأمر بالمعروف والنهي عن المنكر.","section":"l2-kifaya","checkpoint":"l2-kifaya","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q09","type":"recall","phase":"practice","prompt":"ما أقسام السنة؟ مثّل لكل قسم.","answer":"سنة عينية كالوتر ونحوه، وسنة كفائية كالأذان والإقامة وغيرهما.","explain":"السنة هنا تأخذ صورتين: عينية يلزم بها كل واحد كالوتر، وكفائية يكفي فيها بعض المسلمين كالأذان والإقامة. وأضاف الدرس أن ابن عاشر يدخل هذه الأقسام كلها في المندوب، فالمندوب عنده أعمّ من مصطلح غيره.","section":"l2-kifaya","checkpoint":"l2-kifaya","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q10","type":"recall","phase":"practice","prompt":"ما موقف ابن عاشر من المندوب والسنة؟","answer":"المالكية يفرّقون بين المندوب والسنة والرغيبة والتطوع والنافلة، لكن منهج ابن عاشر في منظومته أن المندوب يشمل السنة بقسميها.","explain":"بيّن الدرس خصوصية منهج ابن عاشر: المالكية يفرقون في الأسماء فيميزون السنة من الرغيبة والنافلة والتطوع، أما الناظم فجعل المندوب اسمًا جامعًا يدخل فيه السنة بقسميها؛ وقد نصّ المخطط على أن المندوب «يشمل السنة بقسميها عند ابن عاشر».","section":"l2-kifaya","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q12","type":"recall","phase":"practice","prompt":"وفقًا للدرس، ما السؤالان اللذان يُبنى عليهما تقسيم الحكم الشرعي إلى خمسة أقسام؟","answer":"هل طلب الشارع الفعل أو الترك أو أذن فيهما؟ وهل كان الطلب جازمًا أم غير جازم؟","explain":"يُبنى التقسيم على ملاحظتين مأخوذتين من المخطط: الأولى وجه الطلب، هل وقع على الفعل أم على الترك أم على التخيير بينهما؛ والثانية شدّة الطلب، هل هو جازم أم غير جازم. ومن التقاء الجوابين تتولّد الأحكام الخمسة، فيُعرف الفرض والمندوب من جهة الفعل، والحرام والمكروه من جهة الترك، والمباح عند التخيير.","section":"l2-tree","checkpoint":"l2-tree","difficulty":2},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq2-q13","type":"cloze","phase":"practice","prompt":"الفرض الذي يتعين على كل مكلف بعينه يسمى ______، بخلاف الفرض الذي إذا قام به البعض سقط الإثم عن الباقين ويسمى ______.","answer":"فرض عين، فرض كفاية","explain":"المائز بين القسمين سقوط الإثم وعدمه: فالعيني لا يسقط عن أحد من المكلفين كالصلوات الخمس، والكفائي يرتفع الإثم فيه عن عموم المسلمين بمجرد قيام طائفة به، ولذلك عدّ المخطط من أمثلته إمامة الناس في الصلاة وشهادة القاضي والأمر بالمعروف والنهي عن المنكر.","section":"l2-kifaya","difficulty":3},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"أقسام الحكم الشرعي","url":"fiqh/02-lesson/index.html"},{"question":{"id":"fq3-q01","type":"recall","phase":"pretest","prompt":"ما محاور درس الطهارة؟","answer":"ثلاثة: مدخل تعريفي للمصطلحات، ثم الطهارة وأقسامها، ثم أقسام المياه وأحكامها.","explain":"سار الدرس على ثلاثة محاور متسلسلة: يبدأ بمدخل في المصطلحات لأن الحكم لا يُفهم قبل تصوّر الحدث والنجاسة والماء، ثم ينتقل إلى الطهارة وأقسامها، ويختم بأقسام المياه وأحكامها. وقد أثبتت الخلاصة هذا الترتيب نفسه عند ذكر المحاور الثلاثة.","section":"l3-summary","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q02","type":"recall","phase":"pretest","prompt":"ما الحدث؟ وما النجاسة؟","answer":"الحدث: المنع المترتب على الأعضاء كلها أو بعضها، ويرتفع بطهارة الحدث. والنجاسة (الخبث): ما استقذره الشرع ومنع استباحة الصلاة به، وطهارتها إزالتها عن الثوب والبدن والمكان.","explain":"الحدث وصفٌ حكمي يقوم بالأعضاء كلها أو بعضها فيمنع الصلاة، ولا يرتفع ذلك المنع إلا بطهارة الحدث؛ أما النجاسة فهي العين التي استقذرها الشرع ومنعت إتيان الصلاة بها، وتُزال من الثوب والبدن والمكان. فبينهما فرق في المحلّ والعلاج: هذا منعٌ يُرفع بالتطهّر، وتلك عينٌ تُزيلها الإزالة.","section":"l3-terms","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q03","type":"recall","phase":"practice","prompt":"عرّف الماء المطلق. لماذا سُمّي مطلقًا؟ ولماذا سُمّي طهورًا؟","answer":"هو الماء الذي لم يتغيّر أحد أوصافه الثلاثة بما ينفك عنه غالبًا. سُمّي مطلقًا لأنه لم يُقيَّد بشيء يُنسب إليه، وسُمّي طهورًا لبلوغه الطهارة وكونه مطهِّرًا يرفع الحدث ويرفع حكم الخبث.","explain":"ضابط هذا الماء بقاء أوصافه على أصل خلقتها من غير أن يخالطه ما يزيلها؛ ولهذا وُصف بالمطلق لأنه غير مقيّد بمُزيل، كما وُصف بالطهور لأنه يبلغ الطهارة بنفسه ويصلح لتطهير غيره: يرفع الحدث ويرفع حكم الخبث. ومن صوره في الدرس ماء السماء وماء البحر وماء الأنهار والماء الذائب من الثلج.","section":"l3-terms","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q04","type":"recall","phase":"practice","prompt":"ما الماء المضاف؟ مثّل له.","answer":"هو الماء الذي تغيّر أحد أوصافه باختلاطه بما يفارقه غالبًا، ويصح أن يُنسب إلى مغيِّره، كماء الورد وماء العجين.","explain":"المضاف عكس المطلق: خالطه ما يفارقه غالبًا فتغيّر وصف من أوصافه الثلاثة، فأصبح يصح أن يُضاف إلى مغيّره فيُقال ماء كذا. ومن صوره في الدرس ماء الورد وماء العجين، بخلاف ماء السماء الذي لا يُنسب إلى شيء.","section":"l3-terms","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q05","type":"recall","phase":"practice","prompt":"ما أقسام الطهارة الشرعية؟","answer":"طهارة حدث، وتنقسم إلى صغرى وكبرى. وطهارة خبث، وتنقسم إلى طهارة الثوب وطهارة البدن وطهارة المكان.","explain":"فرّق الدرس بين نوعين من الطهارة بحسب ما يُزال: فنوعٌ يتناول المنع الطارئ على الأعضاء وهو طهارة الحدث، وتفصيلها إلى صغرى وكبرى كالوضوء والغسل؛ ونوعٌ يتناول العين المستقذرة وهو طهارة الخبث، ومواضعها الثوب والبدن والمكان. وكلتا الطهارتين لا تحصل إلا بماء سليم من التغيّر.","section":"l3-tahara","checkpoint":"l3-tahara","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q06","type":"recall","phase":"practice","prompt":"ما أقسام الماء المتغيّر بحسب مغيِّره؟","answer":"ثلاثة: ما تغيّر بنجس فيُطرح. وما تغيّر بطاهر ينفك عنه فهو طاهر غير مطهِّر، يصلح للعادات دون العبادات. وما تغيّر بطاهر ملازم له فهو طهور مطلق.","explain":"مدار التقسيم على سؤال «بماذا تغيّر؟»: فإن كان المتغيّر نجسًا كالدم والبول طُرِح الماء وحرم مطلقًا؛ وإن كان طاهرًا يفارقه عادةً كالصابون والزيت واللبن صلح للعادات كالطبخ والسقي دون العبادات؛ وإن كان طاهرًا ملازمًا كالمغرة والملح والطحلب وطول المكث بقي طهورًا. فكلّما لزم المغيّرُ الماءَ بقي الماء على طهوريته.","section":"l3-water","checkpoint":"l3-water","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q07","type":"recall","phase":"practice","prompt":"ما حكم الماء المتغيّر بالمغرة؟ ولماذا؟","answer":"طهور، يُستعمل في العادات والعبادات، لأن المغرة (الطين الأحمر) تلازم الماء في قراره غالبًا. فحكمه حكم الماء المطلق.","explain":"العلة أنه من قسم الطاهر الملازم: فالمغرة، وهي الطين الأحمر الذي يُصبغ به، تستقرّ في قرار الماء ولا تنفكّ عنه غالبًا، فلا يعدّ تغيّرها ناقلة للماء عن أصل خلقته. ولذلك لحقه حكم الماء المطلق، فيُستعمل في العادات كالسقي وفي العبادات كالوضوء والغسل.","section":"l3-water","checkpoint":"l3-water","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q08","type":"recall","phase":"practice","prompt":"متى يُكره استعمال الماء الطهور؟","answer":"إذا كان كثيرًا وسقطت فيه نجاسة قليلة لم تغيّر أحد أوصافه، فيُكره استعماله إن وُجد غيره.","explain":"هذه حالة وسطى بين الطهور والمطروح: كثرة الماء مع نجاسة قليلة لم تُغيّر لونه ولا طعمه ولا ريحه، فلا يُحكم بنجاسته، ومع ذلك يُكره الاجتراء عليه ما دام هناك غيره؛ فإن لم يوجد غيره جاز، وما عداه من الطهور فاستعماله جائز مطلقًا.","section":"l3-table","checkpoint":"l3-table","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q09","type":"recall","phase":"practice","prompt":"ما معنى «فصل»؟ وما أصل كلمة «بما» في البيت؟","answer":"الفصل هو الحاجز بين الشيئين، وهنا بين المقدمات وقسم الفقه. وأصل «بما» هو «بماء»، حُذفت همزته للتخفيف ولمناسبة الوزن.","explain":"في شرح ألفاظ البيت أن الفصل هو الحاجز بين شيئين، وقد جاء في المتن فاصلًا بين المقدمات التي صدّر بها ابن عاشر وبين قسم الفقه. وأما «بما» في قوله: «وتحصلُ الطهارةُ بما» فأصلها «بماء»، حُذفت همزتها طلبًا للتخفيف ومجاراةً لوزن البيت.","section":"l3-verse","checkpoint":"l3-verse","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q10","type":"recall","phase":"practice","prompt":"ما الفائدة التي ختم بها الأستاذ؟","answer":"حديث الرجل الذي سأل النبي ﷺ عن الوضوء بماء البحر، فقال: «هو الطهور ماؤه الحل ميتته». وفيه أن ماء البحر طهور.","explain":"ختم الدرس بحديث رجلٍ أراد الوضوء بماء البحر ومعه ماء قليل، فأجابه النبي ﷺ: «هو الطهور ماؤه الحل ميتته». ووجه الاستدلال أن وصف ماء البحر بالطهور يجعله من قبيل الماء المطلق الذي يرفع الحدث، وضمّ الحديث إليه حلّ ميتته، فجمع بين حكم الماء وحكم صيده.","section":"l3-verse","checkpoint":"l3-verse","difficulty":1},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q12","type":"recall","phase":"practice","prompt":"وفقًا للدرس، ما الذي يحدد حكم الماء المتغير؟","answer":"ما تغيّر به: فإن تغيّر بطاهر ملازم له فهو طهور، أو بطاهر ينفك عنه فهو طاهر غير مطهِّر، أو بنجس فيُطرح.","explain":"مفتاح الحكم في المخطط ليس مقدار التغيّر بل مصدره: فما تغيّر بطاهر لا يفارق الماء عادةً بقي طهورًا يُستعمل في العادات والعبادات، وما تغيّر بطاهر يفارقه عادةً صلح للعادات دون العبادات، وما تغيّر بنجس طُرِح ولم يُستعمل أصلًا. فالسؤال الدقيق: بماذا اختلط الماء؟","section":"l3-water","difficulty":2},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"fq3-q13","type":"cloze","phase":"practice","prompt":"إذا تغيّر الماء بطاهر ينفك عنه كالصابون أو الزيت أو اللبن، فيصلح ______ دون ______.","answer":"للعادات، العبادات","explain":"هذا هو القسم الأوسط: طاهر غير مطهِّر، لأن مغيّره غير ملازم للماء ولا يفارقه عادةً، فيُستعمل فيما لا يُشترط فيه رفع الحدث كالطبخ والسقي، ولا يصلح لما تُطلب فيه الطهورية كالوضوء والغسل. ويقابله القسم الملازم فحكمه حكم الماء المطلق.","section":"l3-water","difficulty":3},"subject":"fiqh","subjectName":"مادة الفقه","lessonTitle":"كتاب الطهارة","url":"fiqh/03-lesson/index.html"},{"question":{"id":"aq1-q01","type":"recall","phase":"pretest","prompt":"ما الكتاب المعتمد في مادة العقيدة؟ وما المنظومة التي يشرحها؟","answer":"«الشذرات الذهبية في شرح المنظومة الشرنوبية» للإمام إبراهيم بن أحمد المارغني الزيتوني. والمنظومة الشرنوبية لأبي محمد عبد المجيد الشرنوبي الأزهري.","explain":"تجد الجواب في «بطاقة التعريف» أول الدرس: عنوان الكتاب يضمّ في طيّه اسم المنظومة المشروحة، فلاحظ لقب كلٍّ من الرجلين فقد جُعل الشارح «الزيتوني» والناظم «الأزهري»، فتلتقي في الكتاب مدرستان. عنوان الكتاب وحده يدلك على المنظومة التي يشرحها.","section":"aq1-card","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q02","type":"recall","phase":"pretest","prompt":"ماذا يدل عليه كون الشارح زيتونيًا والناظم أزهريًا؟","answer":"يدل على التلاقي والتلاقح بين جامع الزيتونة والجامع الأزهر.","explain":"في «بطاقة التعريف» بند مخصّص عنوانه «دلالة هذا الشرح» يلفت النظر إلى أنّ أحد الرجلين من مدرسة الزيتونة والآخر من مدرسة الأزهر، فيجتمع علم الجامعين في كتاب واحد يُدرَّس ويُقرأ. تأمّل النسبتين المذكورتين مع اسمَي الرجلين لتستحضر المعنى.","section":"aq1-card","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q03","type":"recall","phase":"practice","prompt":"لماذا يُعد علم العقيدة أهم علوم الإسلام؟","answer":"لأنه متعلق بالله تبارك وتعالى، وأعظم ما يتقرب به العبد إلى ربه معرفة توحيده.","explain":"الدرس يبني سلسلة أفكار في «لماذا هو أهم العلوم؟» تبدأ من أنّ العلم متعلق بالله تبارك وتعالى، ولهذا صار أرفع علوم الإسلام. واستُشهد على الغاية بالآية ﴿وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ﴾ من سورة الذاريات، وأعظم ما يتحقق به ذلك معرفة توحيده، فشرف المعلوم هو أساس شرف العلم.","section":"aq1-why","checkpoint":"aq1-why","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q04","type":"recall","phase":"practice","prompt":"ما الذي تتضمنه معرفة التوحيد؟","answer":"العلم بأسماء الله وصفاته وأفعاله، أي ما يجب له تعالى وما يستحيل في حقه وما يجوز.","explain":"في الخطوة الثالثة من سلسلة «لماذا هو أهم العلوم؟» أن معرفة التوحيد تشمل العلم بأسماء الله وصفاته وأفعاله، وهي الأحكام الثلاثة نفسها: ما يجب له سبحانه، وما يستحيل في حقه، وما يجوز. وقد جُعلت هذه الأحكام في «مصطلحات الدرس» مفتاحًا يُبحث به في حق الله وفي حق الأنبياء، فتعلّقها بذات الله هو سرّ شرفها.","section":"aq1-why","checkpoint":"aq1-why","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q05","type":"recall","phase":"practice","prompt":"ما ثمرة هذا العلم؟","answer":"أن يعبد العبد ربه عبادة يستحق بها الثواب، ويسعد بها في الدنيا وفي الآخرة.","explain":"الخطوتان الأخيرتان من السلسلة تربطان العمل بالجزاء: العبادة الصحيحة يستحق بها العبد الثواب، ثم يعقبها السعادة في الدارين. فالغاية من العلم ليست المعرفة وحدها، بل أن تصل المعرفة إلى عبادة صحيحة ثمرتها الجزاء الحسن في الدنيا والآخرة.","section":"aq1-why","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q06","type":"recall","phase":"practice","prompt":"ما المباحث الثلاثة التي تدور عليها مسائل العقيدة؟","answer":"الإلهيات، والنبوات، والسمعيات.","explain":"جدول «المباحث الثلاثة» يعرض ثلاثة صفوف بألوان متمايزة: صف عن ذات الله، وصف عن الأنبياء والمرسلين، وصف عمّا جاء به الخبر والقرآن. وهي الألوان نفسها في الخريطة الذهنية، فاعتمد على المفتاح اللوني والترتيب لتثبيت الأسماء الثلاثة.","section":"aq1-parts","checkpoint":"aq1-parts","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q07","type":"recall","phase":"practice","prompt":"ما موضوع مبحث الإلهيات؟ وما موضوع مبحث النبوات؟","answer":"الإلهيات: ذات الله تبارك وتعالى، من حيث ما يجب له وما يستحيل عليه وما يجوز في حقه. والنبوات: ذات الأنبياء والمرسلين عليهم الصلاة والسلام، من حيث ما يجب لهم وما يستحيل عليهم وما يجوز في حقهم.","explain":"جدول «المباحث الثلاثة» يخصّص لكلّ مبحث عمودين: «موضوعه» و«ما يُبحث فيه». صفّ الله موضوعه ذاته سبحانه، وصفّ الأنبياء موضوعه ذواتهم عليهم الصلاة والسلام، وكلاهما يُبحث فيه بالأحكام الثلاثة: الوجوب والاستحالة والجواز. فالفرق بين المبحثين في المُضاف إليه لا في نوع الأحكام.","section":"aq1-parts","checkpoint":"aq1-parts","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q08","type":"recall","phase":"practice","prompt":"ما السمعيات؟","answer":"المسائل التي أخبر بها الصادق المصدوق ﷺ، وما ثبت بالقرآن الكريم. والعقل يصدّقها ولا يحيلها.","explain":"الجدول يربط مبحث السمعيات بالخبر المنقول: ما أخبر به الصادق المصدوق ﷺ وما ثبت بالقرآن. وفي «مصطلحات الدرس» أن «الصادق المصدوق» وصف له ﷺ: صادق في خبره، مصدَّق فيما يخبر به. وقيد الدرس أن العقل يصدّق هذه المسائل ولا يحيلها، فليست مخالفة للعقل بل مجالًا لا تناله وحدها.","section":"aq1-parts","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q09","type":"recall","phase":"practice","prompt":"ما مقرر السداسي الأول؟ وما الصفات التي سيُتحدث عنها؟","answer":"مبحث الإلهيات، وخاصة ما يجب لله تبارك وتعالى. ويتناول الصفة النفسية (الوجود)، والصفات السلبية، وصفات المعاني، والصفات المعنوية.","explain":"مخطط «مقرر السنة» يخصص السداسي الأول لمبحث الإلهيات، وبداخله أربع بطاقات مرتّبة: الصفة النفسية وهي الوجود، ثم الصفات السلبية، ثم صفات المعاني، ثم الصفات المعنوية. ومعرفة هذا الترتيب تعينك على وضع كل صفة في بابها عند القراءة.","section":"aq1-plan","checkpoint":"aq1-plan","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q10","type":"recall","phase":"practice","prompt":"ما مقرر السداسي الثاني؟","answer":"مبحث النبوات، ثم مبحث السمعيات.","explain":"المخطط نفسه يجعل السداسي الثاني مبحثين بهذا الترتيب: النبوات أولًا ثم السمعيات. وتذكّر من «مصطلحات الدرس» أن السداسي نصف السنة الدراسية، فالمقرر موزّع على سداسيين كاملين لا على سداسي واحد.","section":"aq1-plan","checkpoint":"aq1-plan","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q12","type":"recall","phase":"practice","prompt":"أيّ العبارات التالية تصف المباحث الثلاثة التي تدور عليها مسائل العقيدة وصفًا صحيحًا؟\nأ) الإلهيات: ما يجب لله وما يستحيل عليه وما يجوز في حقه. النبوات: ما يجب للأنبياء والمرسلين وما يستحيل عليهم وما يجوز في حقهم. السمعيات: ما أخبر به الصادق المصدوق ﷺ وما ثبت بالقرآن الكريم.\nب) الإلهيات: ما أخبر به الصادق المصدوق ﷺ. النبوات: ذات الله تبارك وتعالى. السمعيات: ما يجب لله وما يستحيل عليه وما يجوز في حقه.\nج) الإلهيات: ما يجب للأنبياء والمرسلين. النبوات: ما ثبت بالقرآن الكريم. السمعيات: ذات الله تبارك وتعالى.\nد) الإلهيات: ما ثبت بالقرآن الكريم. النبوات: ما أخبر به الصادق المصدوق ﷺ. السمعيات: ما يجب لله وما يستحيل عليه وما يجوز في حقه.","answer":"الإلهيات: ما يجب لله وما يستحيل عليه وما يجوز في حقه. النبوات: ما يجب للأنبياء والمرسلين وما يستحيل عليهم وما يجوز في حقهم. السمعيات: ما أخبر به الصادق المصدوق ﷺ وما ثبت بالقرآن الكريم.","explain":"اضبط المقابلة من جدول «المباحث الثلاثة»: صفّ الإلهيات موضوعه ذات الله، وصفّ النبوات موضوعه ذات الأنبياء، وصفّ السمعيات موضوعه الخبر والقرآن. والخريطة الذهنية تعيد الصفوف نفسها بالألوان، فاحفظ هذا الترتيب لتميّز الوصف الصحيح من المقلوب الذي يبدّل الحقول.","section":"aq1-parts","difficulty":2},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq1-q13","type":"cloze","phase":"practice","prompt":"أكمل الفراغين: إذا كان الطالب يدرس المسائل المتعلقة بذات الله تبارك وتعالى من حيث ما يجب له وما يستحيل عليه وما يجوز في حقه، فهو يدرس مبحث الـ……، وهذا المبحث يُدرَّس في السداسي الـ…… من السنة.","answer":"الإلهيات؛ الأول","explain":"في «مقرر السنة» أن السداسي الأول وُقف على مبحث الإلهيات وما يجب لله، وأن السداسي الثاني للنبوات ثم السمعيات. وفي جدول المباحث أن هذا المبحث موضوعه ذات الله بأحكامه الثلاثة؛ فمتى رأيت السؤال يدور على ذات الله وأحكامه فأنت في هذا المبحث، وموضعه السداسي الأول.","section":"aq1-plan","difficulty":3},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"مدخل إلى علم العقيدة","url":"aqida/01-lesson/index.html"},{"question":{"id":"aq2-q01","type":"recall","phase":"pretest","prompt":"ما المبادئ العشرة؟ ومن نظمها؟","answer":"الحد، والموضوع، والثمرة، والفضل، والنسبة، والواضع، والاسم، والاستمداد، وحكم الشارع، والمسائل. نظمها الإمام الصبّان في ثلاثة أبيات.","explain":"جدول «المبادئ العشرة» يسرد المبادئ مرقّمة من الحد إلى المسائل، ويقابل كل مبدأ بالسؤال الذي يجيب عنه. وقد جاءت مجموعة في ثلاثة أبيات من بحر واحد في أول الدرس، وترتيب الأبيات يوافق ترتيب الجدول، فالحفظ بالبيت يثبّت الترتيب.","section":"aq2-ten","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q02","type":"recall","phase":"pretest","prompt":"عرّف علم العقيدة.","answer":"العلم بالقواعد الشرعية الاعتقادية المكتسب من أدلتها اليقينية.","explain":"هذا هو المبدأ الأول «الحد»، وموضعه الإطار المميّز في أول مبحث الحد، ثم فُصّل في جدول يقسم التعريف إلى أجزاء ويبين ما يدخل في كل جزء وما يخرج به. فالتعريف عتبة ينطلق منها الطالب لتصوّر مادة العلم والحكم على بقية مسائله.","section":"aq2-hadd","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q03","type":"recall","phase":"practice","prompt":"ماذا يخرج بقولنا «الشرعية» و«الاعتقادية» و«المكتسب من أدلتها اليقينية»؟","answer":"«الشرعية» يخرج بها القواعد غير الشرعية. و«الاعتقادية» يخرج بها القواعد الفرعية والأصولية. و«من أدلتها اليقينية» يخرج بها المسائل الفروعية، لأن أدلتها ظنية وقد تكون قطعية.","explain":"جدول الحد يخصّص لكل جزء من التعريف عمودًا عنوانه «ما يخرج به». وجزء «العلم بالقواعد» وحده لا يخرج شيئًا، ثم تُخرج بقية الأجزاء: غير الشرعي، والفرعي والأصولي، والمسائل الفروعية التي أدلتها ظنية وقد تكون قطعية. فاحفظ القيد مع مخرجه في وقت واحد.","section":"aq2-hadd","checkpoint":"aq2-hadd","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q04","type":"recall","phase":"practice","prompt":"لماذا سُميت العقيدة بهذا الاسم؟","answer":"لأنها ما يجزم به المسلم جزمًا ثابتًا لا يقبل الشك والريب. وهي من عقد الحبل إذا ربطه وشدّه.","explain":"في آخر مبحث الحد عمود معنون بـ«لماذا سُميت عقيدة؟» يربط الاسم بالجزم الثابت الذي لا يقبل الشك، ثم يردّه إلى معناه اللغوي في عقد الحبل إذا رُبط وشُدّ. فالتسمية تصوّر لك وصف العقيدة: عقدة وثيقة لا تنحل بالريب.","section":"aq2-hadd","checkpoint":"aq2-hadd","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q05","type":"recall","phase":"practice","prompt":"ما الفرق بين أصول الدين وأصول الفقه؟","answer":"أصول الدين هو علم العقيدة. وأصول الفقه هو أدلة الفقه، وكيفية الاستفادة منها، وحال المستفيد.","explain":"يَعرض أعمدة مبحث الحد مدرستين متجاورتين: أولاهما تتناول القواعد التي تعنى بالاعتقاد، والاعتقاد جازم فبراهينه يقينية، وثانيتهما تتناول أدلة الفقه وكيفية الاستفادة منها وحال المستفيد. فالفرق في الموضوع لا في الشرعية؛ كلاهما علم شرعي لكن هذا في الاعتقاد وذاك في الأدلة.","section":"aq2-hadd","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q06","type":"recall","phase":"practice","prompt":"ما موضوع علم العقيدة؟ ولماذا تناول ذات الأنبياء؟","answer":"ذات الله تعالى، من حيث ما يجب له من صفات الكمال وما يستحيل في حقه من صفات النقص وما يجوز عليه. وتناول ذات الأنبياء لأن الواصل بيننا وبين الله هم الرسل.","explain":"في جدول «الموضوع» ثلاثة صفوف للعقيدة: الإلهيات ثم النبوات ثم السمعيات، وصف الإلهيات موضوعه ذات الله بصفات الكمال والنقص والجواز. وفي إطار مميّز بعد الجدول سبب إضافي: الله هو المقصود الأعظم، لكن الرسل هم الواسطة بيننا وبينه، فاقتضى ذلك أن يبحث العلم في ذاتهم أيضًا.","section":"aq2-mawdu3","checkpoint":"aq2-mawdu3","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q07","type":"recall","phase":"practice","prompt":"ما موضوع الفقه؟ وما موضوع أصول الفقه؟ وما موضوع النحو؟","answer":"الفقه: فعل المكلف من حيث ما يجوز له وما يحل له وما يحرم. وأصول الفقه: الأدلة الإجمالية من حيث ما يعرض لها. والنحو: الكلمة العربية من حيث الإعراب والبناء.","explain":"مبحث «الموضوع» يقابل علم العقيدة بثلاثة علوم أخرى لأن العلوم تتميّز بتميّز موضوعاتها: النحو موضوعه أواخر الكلمات، والفقه موضوعه فعل المكلف، وأصول الفقه موضوعه الأدلة الكلية التي يُستنبط منها الحكم الشرعي. فاجعل لكل علم موضوعه لتميّز بينها.","section":"aq2-mawdu3","checkpoint":"aq2-mawdu3","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q08","type":"recall","phase":"practice","prompt":"ما ثمرة علم العقيدة؟","answer":"تربية الإيمان بالله، وتعزيز الثقة به، وتخليص المسلم من الشبهات والاعتقادات الباطلة، وتحصيل السعادتين في الدنيا وفي الآخرة، والنجاة من ربقة التقليد إلى التبصر والاعتقاد الصحيح.","explain":"في مبحث «الثمرة» قائمة من خمس نتائج، آخرها النجاة من الربقة، والربقة في «مصطلحات الدرس» هي القيد؛ أي فكّ قيد التقليد بالانتقال إلى التبصر بالتفكر والاعتبار. فالعلم لا يزيد معلومة فقط، بل يحرر الاعتقاد من الشبهة والتقليد ويحصّل السعادتين.","section":"aq2-fadl","checkpoint":"aq2-fadl","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q09","type":"recall","phase":"practice","prompt":"بماذا يُقاس شرف العلم؟ وما الذي اجتمع في العقيدة؟","answer":"يُقاس بشرف المعلوم، والموضوع، والغاية، والدليل. وقد اجتمعت كلها في علم العقيدة.","explain":"في مبحث «الفضل» قاعدة: شرف كل علم بشرف متعلقه، ثم يفرّع المخطط أربع جهات: شرف الغاية، وشرف الموضوع، وشرف الدليل، وشرف المعلوم. والمعلوم هنا الإيمان بالله وملائكته ورسله وكتبه واليوم الآخر والقدر خيره وشره. فاجتماع هذه الجهات الأربع هو سبب أفضليته على غيره.","section":"aq2-fadl","checkpoint":"aq2-fadl","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q10","type":"recall","phase":"practice","prompt":"من واضع علم العقيدة؟ وهل يعني اختلافهم أن عقيدتهم مختلفة؟","answer":"أئمة أهل السنة والجماعة: أحمد بن حنبل، وأبو الحسن الأشعري، وأبو منصور الماتريدي ونظراؤهم. ولا، فهم متفقون على أصول العقائد، واختلفوا في مسائل فرعية منها.","explain":"في مبحث «الواضع» بيان أن الواضع هو من قعّد القواعد وأصّل الأصول وألّف ودوّن وردّ على المخالفين، ثم سمّى الأئمة. وفي الإطار قيد مهم: خلافهم في مسائل فرعية لا يمسّ الأصول، فكما أن في الفقه أصولًا وفروعًا فكذلك في العقيدة. فحمل «الواضع» على التقعيد نخبةٌ من الأئمة لا عقيدةً منفردة.","section":"aq2-origin","checkpoint":"aq2-origin","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q11","type":"recall","phase":"practice","prompt":"ما أسماء هذا العلم؟ ولماذا سُمّي «الفقه الأكبر»؟","answer":"علم العقيدة، وعلم التوحيد، وعلم أصول الدين، وعلم الفقه الأكبر. سمّاه به الإمام أبو حنيفة في مقابل الفقه الأصغر (علم الفروع)، لأنه يهتم بأكبر مسائل الإسلام وأهمها.","explain":"في مبحث «الاسم» قاعدة أن تعدد الأسماء يدل على شرف المسمى، ثم تُذكر الأسماء في قائمة مصطلحات. وأقرب مثال إلى الحفظ ما سُمّي به «الفقه الأكبر»: كتابٌ للإمام أبي حنيفة جُعل في مقابل الأصغر وهو علم الفروع، لأن مسائله أكبر مسائل الإسلام وأهمها. فالاسم يذكرك بالمقابلة وبالسبب معًا.","section":"aq2-origin","checkpoint":"aq2-origin","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq2-q12","type":"recall","phase":"practice","prompt":"من أين استمد هذا العلم؟ وما حكم تعلمه؟","answer":"استمد من القرآن الكريم، والسنة النبوية، وإجماع السلف، والبراهين العقلية القطعية. وحكم تعلمه: واجب عيني فيما لا يصح الإيمان إلا به، وواجب كفائي فيما زاد على ذلك من التفصيل وإقامة الأدلة ودحض الشبه.","explain":"مبحث «الاستمداد» يرسم مواد العلم في مخطط من أربع جهات: القرآن والسنة وهما دليل نقلي، وإجماع السلف، والبراهين العقلية القطعية، ويجمعها بقاعدة أن النقل الصحيح يتطابق مع العقل الصريح. وأما حكم تعلمه فقسمان في مخططه: عيني على كل مكلف بالإجماع فيما لا يصح الإيمان إلا به بقدر ما يخرجه من التقليد، وكفائي يسقط بفعل البعض فيما زاد من التفصيل وإقامة الأدلة ودحض الشبه.","section":"aq2-origin","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"المبادئ العشرة لعلم العقيدة","url":"aqida/02-lesson/index.html"},{"question":{"id":"aq3-q01","type":"recall","phase":"pretest","prompt":"لماذا نبدأ قراءة الكتاب بترجمة مؤلفه وناظمه؟","answer":"لأن الإسناد من الدين، ولا يجوز أخذ العلم من الكتب المجهولة. ولولا الإسناد لقال من شاء ما شاء.","explain":"مبحث «لماذا نبدأ بالتراجم؟» يبني الجواب على قاعدة: لولا الإسناد لقال من شاء ما شاء، ويستشهد بقول ابن سيرين: «إن هذا العلم دين فانظروا عمّن تأخذون دينكم». فالتعريف بالكتاب وصاحبيه ضمانٌ لنسبته، ولذلك جُعل الإسناد من الدين، ولا يُؤخذ العلم من كتاب لا يُعرف مؤلفه.","section":"aq3-isnad","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q02","type":"recall","phase":"pretest","prompt":"هل تكفي معرفة المؤلف لاعتماد كتابه؟","answer":"لا. قد يكون المؤلف معروفًا لكنه لا يسير على المقررات المعتمدة، فيُترك قوله. والمقررات المعتمدة هي ما عليه أئمة الزيتونة والأزهر من طريقة أهل السنة والجماعة.","explain":"الإطار الثاني في مبحث «لماذا نبدأ بالتراجم؟» يفرّق بين أمرين: صحة النسبة وصحة المنهج. فمعرفة اسم المؤلف لا تكفي إذ قد يكون معروفًا وهو غير سائر على المقررات المعتمدة، وهي طريقة أهل السنة والجماعة كما عليها أئمة الزيتونة والأزهر؛ فمن خالفها تُرك قوله وإن كان معروفًا.","section":"aq3-isnad","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q03","type":"recall","phase":"practice","prompt":"من شارح الكتاب؟ ومتى وُلد وتوفي؟","answer":"الإمام إبراهيم بن أحمد المارغني الزيتوني التونسي الفقيه المالكي. وُلد بتونس سنة 1865م، وتوفي سنة 1931م، ودُفن بالجلاز.","explain":"في «ترجمة الشارح» بطاقة تعريف ترتّب المولد والنشأة والوفاة مع ذكر موضع الدفن. وهي أرقام يسهل تثبيتها بالتاريخ الميلادي: مولده سنة 1865م ووفاته سنة 1931م. وتأمّل أن البطاقة تجمع اسمه الكامل وصفته الفقهية وبلده قبل التاريخ.","section":"aq3-sharih","checkpoint":"aq3-sharih","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q04","type":"recall","phase":"practice","prompt":"اذكر ثلاثة من شيوخه وثلاثة من تلاميذه.","answer":"من شيوخه: عمر بن الشيخ، وسالم بوحاجب، ومحمود بن الخوجة. ومن تلاميذه: محمد الطاهر بن عاشور، ومحمد الخضر حسين، وبشير النيفر.","explain":"مخطط ترجمة الشارح مقسوم إلى جهتين: عمود لشيوخه وعمود لتلاميذه، وفي وسطه بطاقة عنوانها «مدرّس ومؤلف». فاحفظ الأسماء بالاتجاه لا كقائمة مبعثرة؛ اتجاهٌ يدل على من تلقّى عنهم العلم، واتجاهٌ يدل على من تخرّج به، وبينهما صفحة الشارح.","section":"aq3-sharih","checkpoint":"aq3-sharih","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q05","type":"recall","phase":"practice","prompt":"ما كتبه الثلاثة في العقيدة؟ ولأي مستوى كل كتاب؟","answer":"الشذرات الذهبية للمبتدئين، وطالع البشرى على العقيدة الصغرى للمتوسطين، وبغية المريد بشرح جوهرة التوحيد للمستوى الأعلى.","explain":"مخطط «كتبه في العقيدة» يعرض ثلاثة كتب على ترتيب المستويات: الأول للمبتدئين وهو كتاب المادة، ثم الثاني للمتوسطين على العقيدة الصغرى، ثم الثالث للمستوى الأعلى بشرح جوهرة التوحيد. فالترتيب بالتدرّج في الطلب هو مفتاح الحفظ، وقد قُررت كتبه بجامع الزيتونة المعمور.","section":"aq3-sharih","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q06","type":"recall","phase":"practice","prompt":"من ناظم المنظومة؟ وإلى ماذا ينسب؟","answer":"الإمام أبو محمد عبد المجيد الشرنوبي الأزهري. «الشرنوبي» نسبة إلى قرية الشرنوب في مصر، و«الأزهري» نسبة إلى الجامع الأزهر، وكان من مشايخه.","explain":"في «ترجمة الناظم» بطاقة تجمع الاسم والنسبة والمكانة. والنسبة مركّبة من أصلين: قرية من قرى مصر، والجامع الأزهر الذي كان من أساتذته ومشايخه، فقد كان من مشايخه ومدرّسيه. فتحصيل النسبة يضمّ معًا الموضع والجامع.","section":"aq3-nathim","checkpoint":"aq3-nathim","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q07","type":"recall","phase":"practice","prompt":"كم بيتًا في المنظومة؟ وعلى أي بحر؟ وماذا تضمنت؟","answer":"29 بيتًا من بحر الرجز. وتضمنت من عقائد أهل السنة المحررات، ما يكفي المبتدئ في الإلهيات والنبوات والسمعيات.","explain":"في الخطوة السابعة من «قراءة مقدمة الشارح» (التعريف بالمنظومة): «العقائد» جمع عقيدة، و«التوحيدية» نسبة إلى توحيد الله. فبحرها الرجز وتفعيلته «مستفعلن» ست مرات، وعدد أبياتها تسعة وعشرون، وفي «مصطلحات الدرس» أن المحررات هي المهذبة المخلصة من كثير من الفروع. وتضمنت ما يكفي المبتدئ ولا تستوعب كل المسائل، فليست مختصرة في المقدار فقط بل في المستوى أيضًا.","section":"aq3-read","checkpoint":"aq3-read","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q08","type":"recall","phase":"practice","prompt":"ما الفرق بين النظم والنثر؟ ولماذا يفيد النظم الطلبة؟","answer":"النظم كلام عربي منظوم على وزن، والنثر كلام عربي منثور. وكلاهما يصلح للتعليم. والنظم مفيد لأنه مختصر ويحتوي على مسائل كثيرة يسهل استحضارها.","explain":"في «مصطلحات الدرس» تعريفان متقابلان: النظم كلام عربي منظوم على وزن ويسمى منظومة، والنثر كلام عربي منثور. وقيمته التعليمية أن الوزن يختصر المسائل ويجمعها في قالب واحد، فيسهل استحضارها وقت الحاجة؛ ولهذا جمع الشارح العقائد في منظومة يقرؤها المبتدئ.","section":"aq3-terms","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q09","type":"recall","phase":"practice","prompt":"ما سبب تأليف الشرح؟ وما معنى «شرح ممزوج»؟","answer":"سأله بعض المبتدئين الحافظين للمنظومة أن يشرحها ليفهموا معانيها. والممزوج هو الذي يخلط النظم بالشرح، بخلاف طريقة التعليق: «قال الناظم فهو كذا».","explain":"في الخطوتين الثامنة والتاسعة من «قراءة مقدمة الشارح»: لم يكن للمنظومة شرحٌ، فطلب منه بعض المبتدئين الحافظين لها أن يشرحها ليفهموا معاني ألفاظها، وفيه أن الحفظ أولًا ثم الفهم. ثم بيّن المنهج الممزوج بأنه يخلط النظم بالشرح، خلافًا لطريقة التعليق التي تأتي على صورة «قال الناظم فهو كذا»، وهو المناسب لحال المبتدئين ولو كانوا كبارًا في السن.","section":"aq3-read","checkpoint":"aq3-read","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q10","type":"recall","phase":"practice","prompt":"ما حكم الدليل الإجمالي في العقائد؟","answer":"يكفي في الخروج من التقليد. فالواجب تحصيل ما يصح به الاعتقاد بدليل ولو إجمالي. ومن قصّر فيه فهو آثم، ويصح إيمانه على الصحيح من أقوال أهل العلم.","explain":"في الخطوة العاشرة علةُ اختيار الدليل الإجمالي: أن أئمة التوحيد صرّحوا بأن الأدلة الإجمالية كافية للخروج من التقليد. وموضع الفائدة أن الواجب تحصيل ما يصح به الاعتقاد ولو إجمالًا، ومن قصّر في معرفته فهو آثم مع صحة إيمانه على الصحيح من أقوال أهل العلم. فتأمّل الجمع بين الإثم وصحة الإيمان.","section":"aq3-read","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q11","type":"recall","phase":"practice","prompt":"لماذا سُمّي الكتاب «الشذرات الذهبية»؟","answer":"الشذرة هي القطعة من الذهب، فكأنه حلّى الكتاب بالذهب.","explain":"الخطوة الحادية عشرة في قراءة المقدمة تذكر تمام الاسم وسببه، وفي «مصطلحات الدرس» أن الشذرة القطعة من الذهب وجمعها شذرات. فالتسمية صورة بلاغية تجعل الكتاب قطعًا ذهبية متناثرة، أي مسائل نفيسة مقتطفة، لا كلّ الفن؛ وهذا التصوير يعينك على تذكّر أن الكتاب مقدمة للمبتدئ.","section":"aq3-read","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"aq3-q12","type":"recall","phase":"practice","prompt":"ما حكم التوسل بجاه النبي ﷺ عند الأستاذ؟ وما دليله؟","answer":"مندوب ولا حرج فيه، ولا خلاف فيه بين المذاهب الأربعة. ودليله إرشاد النبي ﷺ الرجل الأعمى أن يتوجه إلى الله بالدعاء ويسأله بحق نبيه. والنافع والضار هو الله.","explain":"مبحث «فائدة: التوسل بجاه النبي ﷺ» يقوم على ثلاثة أعمدة: الحكم، والدليل، والتوضيح. فالحكم يُذكر معه اتفاق المذاهب الأربعة ومشي المسلمين عليه في الأزمنة كلها، والدليل قصة الرجل الأعمى الذي أرشده النبي ﷺ أن يتوجه إلى الله بالدعاء ويسأله بحق نبيه، والتوضيح أن جاهه ﷺ معلوم لا فرق فيه بين حياته ومماته مع أن النفع والضر بيد الله وحده، ولذلك جاز التوسل بالأعمال الصالحة وهي أعراض فمن باب أولى بذاته ﷺ.","section":"aq3-tawassul","checkpoint":"aq3-tawassul","difficulty":1},"subject":"aqida","subjectName":"مادة العقيدة","lessonTitle":"التراجم وقراءة مقدمة الشذرات الذهبية","url":"aqida/03-lesson/index.html"},{"question":{"id":"tj1-q01","type":"recall","phase":"pretest","prompt":"كيف كان علم التجويد يُذكر في القديم؟ ولماذا أُفرد؟","answer":"كان مندمجًا مع كتب النحو والصرف، يذكره أكثر علمائها في آخر الأبحاث. وأُفرد في كتب مستقلة لما وجد العلماء ضعفًا في تلاوة المسلمين لكتاب الله.","explain":"تأمّل تسلسل النشأة في محور «لماذا نتعلم التجويد»: كان ذكر التجويد ملحقًا بمباحث النحو والصرف حتى رأى العلماء ضعفًا في تلاوة المسلمين، فصنّفوا فيه كتبًا خاصة. فالإفراد هنا علاج داءٍ ظهر، لا نشوء علمٍ لم يكن.","section":"tj1-why","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q02","type":"recall","phase":"pretest","prompt":"على من يجب تعلم التجويد؟","answer":"على كل مسلم عاقل بالغ إذا أراد أن يقرأ القرآن، فيتعلم قبل القراءة مخارج الحروف وصفاتها.","explain":"لاحظ أن الوجوب في الدرس مقيّد بحال من عزم على التلاوة لا بكل أحد مطلقًا: فمن أراد أن يقرأ كلام الله لزمه أن يتقن أولًا مواضع خروج الحروف وكيفياتها. واربط ذلك بمحور «الحكم» الذي جعل التعلّم سابقًا للقراءة نفسها لا لاحقًا لها.","section":"tj1-why","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q03","type":"recall","phase":"practice","prompt":"ما فائدة المبادئ العشرة؟","answer":"يمرّ بها طالب العلم مرورًا ليفهم موضوع العلم الذي سيقدم على دراسته وحفظه. وهي لكل علم من علوم الشرع وعلوم الآلة.","explain":"فائدتها وظيفية: هي تمهيدٌ يمرّ عليه الطالب مرورًا خفيفًا فيتكوّن لديه تصوّر عام عن العلم قبل الغوص في مسائله وحفظه، وتشترك فيها علوم الشرع وعلوم الآلة. وتأمّل كيف قدّم الدرس «الحد» أولًا تبعًا لهذا الترتيب.","section":"tj1-ten","checkpoint":"tj1-ten","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q04","type":"recall","phase":"practice","prompt":"عدّد المبادئ العشرة.","answer":"الحد، الموضوع، الثمرة، الفضل، النسبة، الواضع، الاسم، الاستمداد، حكم الشارع، المسائل.","explain":"استحضرها من نظم الأبيات الثلاثة، فالشطر الأول يفتتح بـ«الحدُّ والموضوعُ ثمَّ الثمرةْ» ويُختم في الثالث بـ«مسائلٌ»، ونُظمت ثلاثًا ثلاثًا ليعينك الإيقاع على الاستذكار دون نسيان. وفي الأبيات يقول: «إنَّ مبادئَ كلِّ فنٍّ عشرةْ».","section":"tj1-ten","checkpoint":"tj1-ten","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q05","type":"recall","phase":"practice","prompt":"ما معنى التجويد لغةً واصطلاحًا؟","answer":"لغةً: التحسين. اصطلاحًا: علم يبحث عن مخارج الحروف وصفاتها، ويُطلق أيضًا على إعطاء الحروف حقوقها من المخارج والصفات.","explain":"ابدأ بالمعنى اللغوي فهو مفتاح الاصطلاحي: «التحسين» أصلٌ يجمع التعريفين على فكرة إتقان النطق؛ فأحد التعبيرين ينظر إلى الفن المدوَّن، والآخر إلى الأداء العملي بإعطاء الحروف حقوقها. وقد جمعت «مصطلحات الدرس» بينهما في مدخل واحد.","section":"tj1-hadd","checkpoint":"tj1-hadd","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q06","type":"recall","phase":"practice","prompt":"ما الفرق بين المخرج والصفة؟","answer":"لكل حرف مخرج واحد، وله صفات عدة. فالمخارج جمع مخرج، وهو موضع خروج الحرف.","explain":"القاعدة التي يضبطها الدرس: موضع خروج الحرف واحد لا يتعدد، أما الكيفيات التي تعرض له فأكثر من واحدة؛ ولهذا قيل لكل حرف مخرج واحد وصفات عدة. وقرّبه الشيخ بحرف الصاد: له مسار صوتي واحد وصفات خمس.","section":"tj1-hadd","checkpoint":"tj1-hadd","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q07","type":"recall","phase":"practice","prompt":"اذكر صفات حرف الصاد وعرّف كل صفة.","answer":"الهمس: جريان النفس. الصفير: حدّة في الصوت. الرخاوة: جريان الصوت. الاستعلاء: تفخيم الحرف وتسمينه. الإطباق: انطباق طائفة عظمى من اللسان على الحنك الأعلى.","explain":"اجمعها من مخطط الدرس لحرف الصاد: هي خمس كيفيات متمايزة لا مجرد أسماء؛ فالهمس نفسٌ يجري عند النطق، والصفير حِدّة كصوت الطائر، والرخاوة استمرار صوت لا انحباس ولا توسط، ثم الاستعلاء تفخيمٌ وتسمين، والإطباق انضمام معظم اللسان إلى الحنك الأعلى. ويمكنك مراجعة تعريف كل واحدة في «مصطلحات الدرس».","section":"tj1-sad","checkpoint":"tj1-sad","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q08","type":"recall","phase":"practice","prompt":"ما حروف الإطباق؟","answer":"أربعة: الصاد والضاد والطاء والظاء.","explain":"احتصرها بالجملة المحورية في درس الاستعلاء والإطباق: عددها أربعة، وكلها تشترك في الاستعلاء؛ وقد رسمته الخريطة في وسط دائرة الاستعلاء حيث اجتمعت «ص ض ط ظ». فعددٌ محدود يسهل ضبطه، إذ لا إطباق في غيرهن.","section":"tj1-itbaq","checkpoint":"tj1-itbaq","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q09","type":"recall","phase":"practice","prompt":"هل كل حرف مستعلٍ مطبق؟ وضّح بمثال.","answer":"لا. كل مطبق مستعلٍ، وليس كل مستعلٍ مطبقًا. فالقاف مستعلية وليست مطبقة.","explain":"القاعدة في الدرس أن حروف الإطباق تدخل ضمن المستعلية، لكن العكس لا يصح؛ ويكفي شاهد واحد يكسر التلازم، وهو حرف القاف الذي يرتفع اللسان عنده بالتفخيم دون أن ينطبق على الحنك. فالإطباق أخصّ من الاستعلاء، وأحدهما أعمّ من الآخر.","section":"tj1-itbaq","checkpoint":"tj1-itbaq","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q10","type":"recall","phase":"practice","prompt":"ما الفرق بين الحركة الأصلية والحركة العارضة؟","answer":"الأصلية ذاتية للحرف. والعارضة نستعيرها للتوصل بالنطق إلى الحرف الذي يليها، وليست أصلية.","explain":"ميّزهما بمصدر كل واحدة: الأصلية جزء من بنية الحرف لا تُستعار، وهي الضم أو الكسر أو الفتح الذي يقوم بالحرف أصالةً؛ أما العارضة فوسيلة نطقية مؤقتة تُلجأ إليها عند تعذّر النطق ثم تزول بانتفاء سببها، ولذلك ليست ذاتية ولا أصلية.","section":"tj1-arid","checkpoint":"tj1-arid","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q11","type":"recall","phase":"practice","prompt":"لماذا تُكسر النون في «لمن ارتضى»؟","answer":"لأن النون الساكنة يلقاها ساكن بعدها، ويستحيل النطق بحرفين ساكنين معًا. فيُحذف سكون الأول ويؤتى بكسرة عارضة للتوصل إلى الحرف الذي يليه.","explain":"تتبّع خطوات المثال: التقى ساكنان فامتنع النطق بهما معًا، فلم يبقَ إلا تحريك الأول؛ فسقط سكونه وجيء بحركة تُعين على العبور إلى ما بعدها. فالكسر هنا علاج ضرورة لا أصلٌ في النون، ولذلك سماها الشيخ «كسرة عارضة» لا أصلية ولا ذاتية.","section":"tj1-arid","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj1-q13","type":"recall","phase":"practice","prompt":"ما العلاقة الصحيحة بين الاستعلاء والإطباق كما وردت في الدرس؟","answer":"كل مطبق مستعلٍ، وليس كل مستعلٍ مطبقًا. فالقاف مستعلية وليست مطبقة، أما الصاد والضاد والطاء والظاء فهي مستعلية ومطبقة معًا.","explain":"المعيار الذي رسمه الدرس دائرتان: دائرة أوسع للاستعلاء، وداخلها دائرة أصغر لحروف الإطباق؛ فأثبت التقاطع دون التطابق، ثم أخرج القاف من الدائرة الصغرى ليبقى في الكبرى وحده مستعليًا غير مطبق. فاجعل «ص ض ط ظ» في الداخل، والقاف على الحد الخارجي.","section":"tj1-itbaq","difficulty":2},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مقدمة علم التجويد وتعريفه","url":"tajwid/01-lesson/index.html"},{"question":{"id":"tj2-q01","type":"recall","phase":"pretest","prompt":"ما موضوع علم التجويد؟","answer":"الكلمة القرآنية من حيث هي، أي من حيث مخارج حروفها وصفاتها حيثما وقعت في كتاب الله، وما يتكون منه العلم كالمدود والإخفاء والإدغام.","explain":"الموضوع يجيب عن سؤال «فيمَ يبحث؟»: نطاقه الكلمة القرآنية بذاتها لا بمعناها، فيُبحث في أصول الحروف أي مخارجها وصفاتها أينما وقعت في التنزيل، ثم فيما يتكوّن منه العلم من المدود والإخفاء والإدغام. وهذا ما يفرّقه عن الثمرة والحكم.","section":"tj2-nisba","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q02","type":"recall","phase":"pretest","prompt":"إلى أي علم ينتسب التجويد؟","answer":"هو من العلوم العربية، وداخل في علم التصريف، ولذلك يُذكر في آخر بعض كتب الصرف كالشافية.","explain":"تجده في محور «الموضوع والنسبة»: التجويد داخلٌ في العلوم العربية وفي التصريف خاصة، حتى إن بعضهم جعله خاتمةً لكتاب في الصرف كـ«الشافية». فمباحث الحروف امتداد طبيعي لمباحث الصرف، ولذلك أُلحق به ولم يُستقل عنه.","section":"tj2-nisba","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q03","type":"recall","phase":"practice","prompt":"ما ثمرة علم التجويد؟","answer":"حفظ اللسان من اللحن في قراءة القرآن، ليقرأ قراءة صحيحة سليمة فينال رضا الله وتتحقق له سعادة الدارين.","explain":"الثمرة غاية عملية لا تعريفية، وهي مثبتة في صفّ «الثمرة» من جدول المبادئ: ضبط اللسان حتى لا يزلّ في اللفظ، فيبلغ القارئ أداءً سليمًا يترتب عليه نيل الرضا والفوز في الدارين. لاحظ الفرق بينها وبين الموضوع: هذه نتيجة، وذاك ميدان البحث.","section":"tj2-table","checkpoint":"tj2-table","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q04","type":"recall","phase":"practice","prompt":"من أين يستمد التجويد فضله؟","answer":"من شرف موضوعه، وهو كلام الله عز وجل القديم الذي لا يُمَلّ سماعه. وهو علم شرعي.","explain":"مصدر الشرف ليس كون التجويد فنًّا صوتيًّا، بل لأن مادّته كلام الله القديم الذي لا يُمَلّ سماعه، ولهذا وُصف في جدول المبادئ بأنه من أشرف العلوم. فقرين الشرف هنا شرعية العلم لا غرابته.","section":"tj2-table","checkpoint":"tj2-table","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q05","type":"recall","phase":"practice","prompt":"هل وضع النبي ﷺ قواعد التجويد؟ ومن واضعه نظريًا؟","answer":"لا، وإنما علّم القراءة بالتلقي والمشافهة. وقيل: واضعه الخليل بن أحمد الفراهيدي، وقيل: أبو الأسود الدؤلي، وقيل: حفص بن عمر الدوري، وقيل: أئمة القراء.","explain":"افرق بين طريق الأداء وطريق التدوين: النبي ﷺ علّم بالمشافهة والتلقّي فلم يضع مصنّفًا ولم يقسّم المدود، ثم إن نسبة التقعيد النظري لم تُجزم لواحد بل وردت بصيغة الترديد بين جماعة. فالتلقّي أمرٌ متحقّق، أما الواضع فمحلّ خلاف.","section":"tj2-nisba","checkpoint":"tj2-nisba","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q06","type":"recall","phase":"practice","prompt":"من أين استمد التجويد؟ وكيف وصل إلينا؟","answer":"من كيفية قراءة النبي ﷺ عن جبريل عن اللوح المحفوظ. نقله الصحابة بالمشافهة، ثم التابعون، ثم أئمة القراءة والمشايخ بسند متصل دون انقطاع.","explain":"تتبّع «سلسلة نقل العلم» من أعلاها: منبع الكيفية قراءة النبي ﷺ عن جبريل عن اللوح المحفوظ، ثم انتقلت بالمشافهة من فم إلى فم عبر الصحابة والتابعين والمشايخ. وشرط قبول هذا النقل اتصال السند بلا انقطاع، وبه بقي العلم غضًّا طريًّا.","section":"tj2-sanad","checkpoint":"tj2-sanad","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q07","type":"recall","phase":"practice","prompt":"ما حكم تعلم التجويد؟","answer":"فرض كفاية: إذا تعلمه بعض أهل القرية سقط الإثم عن الباقين، وإن خلت منه أثم أهلها كلهم. وهو فرض عين على من أراد أن يقرأ القرآن.","explain":"الحكم يتغيّر بتغيّر حال المكلّف: نُظر إلى الأمة فصار كفائيًا يسقط بقيام البعض، ونُظر إلى من عزم على القراءة فصار متعيّنًا في حقه. ودليل كفايته أن البلد إذا خلا من متقنٍ أثم أهله جميعًا؛ وقد ربط الدرس هذا بباب الفرض العيني والكفائي في درس الفقه.","section":"tj2-hukm","checkpoint":"tj2-hukm","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q08","type":"recall","phase":"practice","prompt":"ما أدلة وجوب التجويد؟","answer":"الكتاب: «ورتل القرآن ترتيلا». والسنة: حديث «رب قارئ للقرآن والقرآن يلعنه»، وحديث حذيفة «اقرؤوا القرآن بلحون العرب». والإجماع: أجمعت الأمة على وجوبه ولم يخالف أحد.","explain":"الأدلة ثلاثة أنواع لا واحد، وكلٌّ يعضد الآخر: نصٌّ قرآني بصيغة الأمر دلّ على الوجوب، وأثران نبويان أحدهما تحذيري والآخر في هيئة القراءة، ثم إجماع الأمة المعصومة دون مخالف. فرتّبها كما رتّبها الدرس: كتاب فسنة فإجماع.","section":"tj2-adilla","checkpoint":"tj2-adilla","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q09","type":"recall","phase":"practice","prompt":"ماذا قال علي رضي الله عنه في معنى الترتيل؟ وماذا يُفهم منه؟","answer":"قال: الترتيل هو تجويد الحروف ومعرفة الوقوف. فمن تعلم تجويد الحروف دون معرفة الوقوف لا يُؤتمن على علمه ولا يُؤخذ منه.","explain":"قول علي رضي الله عنه يضمّ ركنين: إحسان النطق بالحروف ومعرفة مواضع الوقف والابتداء، وقد أورده الدرس تحت الدليل الأول من أدلة الوجوب. ويُستخرج منه التنبيه الوارد في «تنبيه عن الوقوف»: من أتقن الحروف وحده لم يُوثق بعلمه؛ فمعرفة الوقوف شرطٌ في الائتمان لا زيادة.","section":"tj2-adilla","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q10","type":"recall","phase":"practice","prompt":"عرّف بمتن تحفة الأطفال.","answer":"متن للشيخ الجمزوري، تلقته الأمة بالقبول، جمع أهم مباحث التجويد ليسهل على المبتدئين تعلمها وحفظها. وأفضل شروحه شرح ناظمه، اقتصر فيه على ما لا بد منه.","explain":"بطاقة المتن تجمع أربعة أمور: نسبته إلى الجمزوري، وقبول الأمة له فكثُر حفّاظه وشرّاحه، وجمعه لأهم مباحث التجويد في صيغة تُعين المبتدئ على الحفظ، وتفضيل شرح الناظم نفسه لاقتصاره على ما لا بد منه. فالقِصر والاقتصار هنا ميزة اختارها المؤلف لحال القارئ المبتدئ.","section":"tj2-tuhfa","checkpoint":"tj2-tuhfa","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q12","type":"recall","phase":"practice","prompt":"ما الحكمة من كون تعلم التجويد فرض كفاية على الأمة وفرض عين على من أراد قراءة القرآن؟","answer":"قراءة القرآن واجبة على من أرادها، فوجب عليه أن يتعلم مخارج الحروف وصفاتها ليصح أداءه. فإذا تعلمه بعض أهل القرية سقط الإثم عن الباقين، وإن خلت القرية من عالم به أثم أهلها كلهم.","explain":"اربط الحالتين بالحاجة: من قصد التلاوة احتاج إلى المخرج والصفة ليصحّ أداؤه فصار متعيّنًا في حقه؛ أما مجموع الأمة فلا يلزم كل فرد أن يتخصص، فإن وُجد من يقوم بالعلم اندفع الحرج عن سوادهم. وبهذا يظهر الجمع بين الحكمين لا التعارض، ويؤكد الدرس بصندوق «ربط بالفقه».","section":"tj2-hukm","checkpoint":"tj2-hukm","difficulty":2},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj2-q13","type":"cloze","phase":"practice","prompt":"إذا تعلم التجويد بعض أهل القرية، فإن الإثم يسقط عن __________؛ أما إذا خلت القرية من عالم به فإن __________ أهلها.","answer":"الباقين، يأثم","explain":"المفتاح هنا منطوق قاعدة الفرض الكفائي في مخطط «الحكم»: كفايةُ البعض تُسقط الحرج عن سواد الناس، وفَقْدُ المتخصص يجعل التقصير جماعيًا. ولا تخلطه بالفرض العيني الخاص بمن أراد القراءة، فقد فرّق الدرس بين الحالين.","section":"tj2-hukm","difficulty":3},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"مبادئ علم التجويد: الموضوع والثمرة والفضل والحكم","url":"tajwid/02-lesson/index.html"},{"question":{"id":"tj3-q01","type":"recall","phase":"pretest","prompt":"من هو ناظم تحفة الأطفال؟","answer":"سليمان ابن حسين بن محمد الجمزوري","explain":"ينسب الناظم نفسه في أول أبياته حيث يقول «دوماً سليمانُ هو الجمزوري»، ثم يُلحق نسبه في خريطة الدرس بابن حسين بن محمد. ومن لطائف الدرس أن التعريف جاء على لسان الناظم لا من كلام الشارح.","section":"tj3-text","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q02","type":"recall","phase":"pretest","prompt":"ما اسم الشرح الذي وضعه الناظم على نظمه؟","answer":"فتح الأقفال بشرح تحفة الأطفال","explain":"التسمية مثبتة في بند خاص من «سبب النظم وتسمية الشرح»، وجاءت مركّبة من عنوانين اختارهما الناظم لشرحه على نظمه. فاحفظ الاسم كاملًا كما صاغه المؤلف لا مختصرًا، فهو عنوان الشرح لا عنوان المتن.","section":"tj3-cause","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q03","type":"recall","phase":"practice","prompt":"على من اعتمد الناظم في أصل شرحه؟","answer":"شرح ولد شيخنا الشيخ محمد الميهي","explain":"في بند «الأصل» ينصّ الناظم أنه جعل أصله شرحًا لولد شيخه الميهي الذي سمّاه الدرس باسمه. فالمعنى أن تأليفه لم يكن ابتداءً محضًا بل بنى على شرح سابق، وهذا ما يميّز منقولَ الناظم من تصرّفاته.","section":"tj3-cause","checkpoint":"tj3-cause","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q04","type":"recall","phase":"practice","prompt":"من هو الذي نقل عنه الناظم؟","answer":"شيخنا نور الدين علي بن عمر بن حمد بن عمر بن ناجي بن قنيش (أو فنيش) الميهي","explain":"الاسم مطوّل بنسبه، وهو مثبت ضمن محور شيوخ الناظم في قائمة «تحقق من فهمك» حيث دُوّن كاملًا. ويُفهم منه أنه من لقّن الناظم علمه، وقد أشارت الخريطة إلى نسبته الميهيّة في مقابل محمد الميهي صاحب الأصل.","section":"tj3-memorize","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q05","type":"recall","phase":"practice","prompt":"ما معنى الحمد؟","answer":"الثناء الحسن الثابت بالاختصاص لله تعالى، باللسان على الوصف الجميل من نعمه أو غيرها","explain":"تعريف «الحمد» في المصطلحات يقيّد الثناء بثلاثة قيود: كونه حسنًا، وثابتًا، ومنسوبًا إلى الله وحده بالاختصاص؛ ثم أضاف إليه أن يكون باللسان على وصفٍ جميل. وقد شرح به الدرس افتتاح الناظم بحمد الله قبل الصلاة على النبي ﷺ.","section":"tj3-terms","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q06","type":"recall","phase":"practice","prompt":"ما معنى الصلاة على النبي ﷺ؟","answer":"طلب من الله أن ينزل رحمته المقرونة بالتعظيم على سيدنا محمد","explain":"الصلاة هنا طلبٌ من العبد يُوجّه إلى الله، مصحوبٌ برحمة مقترنة بالتعظيم لسيدنا محمد ﷺ؛ وهذا هو التعريف الذي شرح به الدرس تقديم الناظم الصلاة على الآل ومن تلا. ويجمع الآلُ الأولين والآخرين ممن آمن به.","section":"tj3-terms","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q07","type":"recall","phase":"practice","prompt":"ما معنى القبول؟","answer":"ترتيب الغرض المطلوب للداعي على دعائه، كترتيب الثواب على الطاعة","explain":"القبول في الدرس ليس مجرد إجابة الدعاء، بل تنزيلُ المطلوب في رتبته كما ينزّل الأجر على الطاعة؛ فهو ترتيب الغرض المطلوب على الدعاء. وقد قربه الناظم بالثواب ليكشف المعنى، فاحفظ التشبيه فهو مفتاح الحدّ.","section":"tj3-terms","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q08","type":"recall","phase":"practice","prompt":"ما الفرق بين الأجر والثواب؟","answer":"الأجر ما كان في مقابلة العمل، والثواب تفضيلًا وإحسانًا من الله، ويستعمل كل منهما بمعنى الآخر","explain":"تأمّل لفظ «يتفضل بإعطائه» في تعريف الثواب بالمصطلحات: فالجزاء المقدر عند الله يُمنح على جهة الفضل لا على جهة المعاوضة الدقيقة، وهذا معنى كونه تفضيلًا وإحسانًا. أما الأجر فيُستعمل في مقابلة العمل، ولتقارب المعنيين يجري استعمال أحدهما مكان الآخر.","section":"tj3-terms","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q09","type":"recall","phase":"practice","prompt":"من هو الطالب في الفن؟","answer":"من شرع في الفن ولم يستقل بتصوير المسائل ولم يقدر على إقامة الأدلة","explain":"التعريف يحدّ الطالب بثلاث صفات: أنه بدأ في الفن، ولم يستقل ببيان مسائله، ولم يقدر على إقامة أدلتها؛ فهو المبتدئ في مقابل المريد. وافهم من ذلك أن الوصف مقاميّ لا ثابت، ينتقل منه الطالب إذا ملك التصوير والاستدلال.","section":"tj3-terms","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q10","type":"recall","phase":"practice","prompt":"من هو المريد؟","answer":"الطالب المتقدم","explain":"المريد في الدرس هو المقام الأعلى من الطالب، أي الذي جاوز طور البداية وتقدّم في الفن؛ فإذا كان الطالب مبتدئًا لم يستقل بعد، فالمريد قد ارتقى درجة فوقه. ومن هنا يُفهم وصف النظم في أبيات المقدمة بأنه «للمريد».","section":"tj3-terms","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q12","type":"recall","phase":"practice","prompt":"لماذا ابتدأ الناظم نظمه بالبسملة والحمدلة؟","answer":"اقتداءً بالكتاب العزيز الذي بدأت به سورة الفاتحة، وتبعًا للسنة النبوية في حديث «كل أمر ذي بال لا يبدأ فيه ببسم الله الرحمن الرحيم فهو أقطع بركة».","explain":"بنى الناظم افتتاحه على أصلين ذكرهما الدرس: اقتفاء أثر القرآن حيث استُفتحت الفاتحة بالبسملة، والسير على ما جاءت به السنة في ابتداء كل أمر ذي بال بذكر الله. وصيغة الحديث تفيد أن تَركه يقطع البركة، فكان الابتداء طلبًا للبركة لا مجرد عادة.","section":"tj3-basmala","checkpoint":"tj3-basmala","difficulty":2},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj3-q13","type":"cloze","phase":"practice","prompt":"الطالب في الفن هو من __________ فيه ولم يستقل بتصوير المسائل ولم يقدر على إقامة الأدلة.","answer":"شرع","explain":"المطلوب فعلٌ يدلّ على البداية في الفن، وهو أول شرط في حدّ الطالب المقابل للمريد المتقدم: فذاك قد تجاوز البداية، وهذا إنما شرع فيها ولم يستقل بعد بالتصوير ولا بالاستدلال.","section":"tj3-terms","difficulty":3},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"نظم المقدمة — مقدمة تحفة الأطفال","url":"tajwid/03-lesson/index.html"},{"question":{"id":"tj4-q01","type":"recall","phase":"pretest","prompt":"ما أحكام النون الساكنة والتنوين؟","answer":"أربعة: الإظهار، والإدغام بقسميه، والإقلاب، والإخفاء","explain":"البيت المطلع يجملها: «لِلنُّونِ إِنْ تَسْكُنْ وَلِلتَّنْوِينِ — أَرْبَعُ أَحْكَامٍ فَخُذْ تَبْيِينِي»؛ والحكمان الأخيران أُجّلا إلى حلقٍ قادمة كما ذكر الشيخ، وهذا الدرس يعرض الحكم الأول: الإظهار.","section":"tj4-four","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"أحكام النون الساكنة والتنوين: الإظهار","url":"tajwid/04-lesson/index.html"},{"question":{"id":"tj4-q02","type":"recall","phase":"pretest","prompt":"عرّف الإظهار لغةً واصطلاحًا.","answer":"لغةً: البيان. واصطلاحًا: إخراج كل حرف من مخرجه من غير غنة","explain":"التعريف الاصطلاحي فيه ثلاثة قيود: إخراجٌ، ومن مخرج الحرف لا من موضع آخر، ومن غير غنة؛ لأن الغنة تكون مقرونةً بالإخفاء والإدغام الناقص، والإظهار عكس الإخفاء.","section":"tj4-izhar","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"أحكام النون الساكنة والتنوين: الإظهار","url":"tajwid/04-lesson/index.html"},{"question":{"id":"tj4-q03","type":"cloze","phase":"pretest","prompt":"التنوين نون ساكنة زائدة تلحق آخر الأسماء لفظًا وتسقط __________، ولا يكون إلا متطرفًا.","answer":"خطًا","explain":"التنوين يثبت لفظًا في آخر الاسم ويسقط في الخط، فتُكتب مكانه الضمة أو الفتحة أو الكسرة؛ ولذلك لا يكون إلا متطرفًا لأنه لا يكون إلا من كلمتين.","section":"tj4-two","difficulty":1},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"أحكام النون الساكنة والتنوين: الإظهار","url":"tajwid/04-lesson/index.html"},{"question":{"id":"tj4-q04","type":"recall","phase":"practice","prompt":"ما الفرق بين النون الساكنة والتنوين من حيث الخط والمواضع؟","answer":"النون الساكنة تثبت خطًا ولفظًا في الوصل والوقف، وتقع في الأسماء والأفعال والحروف متوسطة ومتطرفة؛ والتنوين نون ساكنة زائدة تلحق آخر الأسماء وتسقط خطًا، ولا يكون إلا متطرفًا","explain":"أفاد الشيخ أن التنوين من خواص الأسماء لا يدخل إلا عليها، وأن النون الساكنة أعم؛ فهما مختلفان في الحالتين: تثبت النون خطًا ولفظًا، والتنوين يثبت لفظًا ويسقط خطًا.","section":"tj4-two","difficulty":2},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"أحكام النون الساكنة والتنوين: الإظهار","url":"tajwid/04-lesson/index.html"},{"question":{"id":"tj4-q05","type":"recall","phase":"practice","prompt":"ما ترتيب حروف الحلق الستة كما ورد في الدرس؟","answer":"من أقصى الحلق إلى أدناه: الهمزة، الهاء، العين، الحاء، الغين، الخاء","explain":"رتبها الشيخ على ترتيبها في المخرج كما ذكره ابن الجزري والشاطبي؛ فالهمزة من أقصى الحلق والنون تليها في المخرج، والعين والحاء من وسط الحلق وهما مهملتان أي بلا نقطة، والغين والخاء من أدناه وهما معجمتان أي منقوطتان.","section":"tj4-izhar","difficulty":2},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"أحكام النون الساكنة والتنوين: الإظهار","url":"tajwid/04-lesson/index.html"},{"question":{"id":"tj4-q06","type":"cloze","phase":"practice","prompt":"العين والحاء مهملتان أي بلا نقطة، والغين والخاء معجمتان أي __________.","answer":"منقوطتان","explain":"العرب قديمًا لا تنقط الحروف وإنما تصفها؛ فالمهمل هو المتروك بلا نقطة والمعجم هو المنقوط، وهذا التوصيف يبيّن الحروف المتشابهة ويمنع الالتباس بين العين والحاء وبين الغين والخاء.","section":"tj4-izhar","difficulty":2},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"أحكام النون الساكنة والتنوين: الإظهار","url":"tajwid/04-lesson/index.html"},{"question":{"id":"tj4-q07","type":"recall","phase":"practice","prompt":"ماذا يحدث لمن قرأ ﴿وَالْمُنْخَنِقَةَ﴾ بسرعةٍ متعجلة؟","answer":"يصير حرف الخاء بمنزلة حروف الشدة فينزل النطق منزلة الإخفاء من غير قصد","explain":"الخاء حرفٌ رخو لا من حروف التوسط ولا من حروف الشدة؛ فمن عدّى النون الساكنة بسرعة صار كأنه يخفيها؛ فالواجب التلفظ بلطفٍ وتأنيٍ على وجه التؤدة حتى يظهر الحرف كاملًا من مخرجه.","section":"tj4-notice","difficulty":2},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"أحكام النون الساكنة والتنوين: الإظهار","url":"tajwid/04-lesson/index.html"},{"question":{"id":"tj4-q08","type":"recall","phase":"practice","prompt":"اذكر ثلاثة أمثلة لإظهار النون الساكنة والتنوين: من كلمةٍ ومن كلمتين ومن التنوين.","answer":"من كلمة: ﴿يَنْحِتُونَ﴾. ومن كلمتين: ﴿وَمِنْ آمَنَ﴾. ومن التنوين: ﴿عَلِيمٌ حَكِيمٌ﴾","explain":"الإظهار يأتي مع النون الساكنة من كلمةٍ أو من كلمتين، ومع التنوين في كلمتين دائمًا لأن التنوين في آخر الكلمة الأولى؛ ولكل حرفٍ من الحروف الستة ثلاثة أمثلة كما في شبكة الدرس.","section":"tj4-examples","difficulty":3},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"أحكام النون الساكنة والتنوين: الإظهار","url":"tajwid/04-lesson/index.html"},{"question":{"id":"tj4-q09","type":"recall","phase":"practice","prompt":"ما الشاهد في ﴿وَهُمْ يَنْهَوْنَ عَنْهُ﴾ وما الدرس منه؟","answer":"فيها موضعان للإظهار: نونٌ ساكنة قبل الهاء في كلمة واحدة، ونونٌ ساكنة قبل الهمزة من كلمتين","explain":"في «يَنْهَوْنَ» وقعت النون الساكنة متبوعةً بالهاء في نفس الكلمة، وفي آخرها وقعت متبوعةً بالهمزة في كلمة «عَنْهُ»؛ فوجب إظهار النون في الموضعين، والشيخ أورد المثال مبيّنًا موضعيه.","section":"tj4-examples","checkpoint":"tj4-examples","difficulty":3},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"أحكام النون الساكنة والتنوين: الإظهار","url":"tajwid/04-lesson/index.html"},{"question":{"id":"tj4-q10","type":"recall","phase":"practice","prompt":"لماذا حذفت تاء التأنيث من «أربعة» في قوله «أربعة أحكام»؟","answer":"للضرورة الشعرية؛ لأن البيت من بحر الرجز، فإذا أثبت التاء وقع الكسر في البيت","explain":"العدد من واحد إلى تسعة يخالف المعدود؛ فمع «أحكام» يأتي مجرورًا بلا تاء: أربعة أحكام، ولزم الناظم أن يقول «أربعة أحكام» لئلا ينكسر البيت، فحذف التاء للضرورة الشعرية.","section":"tj4-bayt","checkpoint":"tj4-bayt","difficulty":2},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"أحكام النون الساكنة والتنوين: الإظهار","url":"tajwid/04-lesson/index.html"},{"question":{"id":"tj4-q11","type":"recall","phase":"practice","prompt":"كيف تُعرب «أحكام النون الساكنة والتنوين» كما في البيت، وما الوجه المشهور عند الشيخ؟","answer":"الوجه المشهور: خبرٌ لمبتدأٍ محذوف تقديره «هذه أحكام النون الساكنة والتنوين مقررة»؛ وتقع أيضًا مفعولًا به لفعلٍ محذوف، أو مجرورًا بحرف جرٍ محذوف، أو مضافًا إليه","explain":"الحكم في اللغة إثباتٌ لأمرٍ آخر أو نفيه، فـ«أحكام النون الساكنة والتنوين» في البيت خبرٌ لمبتدأٍ محذوف؛ وذكر الشيخ أن من فقه المعرب أن يأتي بالوجوه، لكن المقدَّم والمشهور الخبرية.","section":"tj4-hukm","checkpoint":"tj4-hukm","difficulty":2},"subject":"tajwid","subjectName":"مادة التجويد","lessonTitle":"أحكام النون الساكنة والتنوين: الإظهار","url":"tajwid/04-lesson/index.html"},{"question":{"id":"sr1-q01","type":"recall","phase":"pretest","prompt":"ما تعريف السيرة النبوية؟","answer":"كل ما يتصل بحياة النبي ﷺ منذ مولده حتى وفاته","explain":"في قسم «تعريف السيرة والمغازي» أن السيرة تشمل وقائع العهدين المكي والمدني، ويوصفها الدرس بأنها تاريخٌ كلٌّ لا يتجزأ ولا تنفصل حلقاته. ومن ثمّ لا يصح قصرها على حقبة واحدة من حياته ﷺ، بل تدخل فيها كل أطواره.","section":"h1-def","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q02","type":"recall","phase":"pretest","prompt":"ما الفرق بين السيرة والمغازي؟","answer":"السيرة تشمل كل حياة النبي ﷺ، والمغازي مختصة بأخبار الغزو والصرايا والبعوث بعد الهجرة","explain":"الحدّ الفاصل بين العلمين هو الهجرة: فخبر معركة وقعت بعدها يُدرس في المغازي، أما مولده ﷺ ونسبه وبعثته فيُدرسان في السيرة. ويبيّن الدرس أن العلمين يشتركان في سرد الحقبة التاريخية قبل البعث وبعدها، وأن غلبة اسم السيرة جاءت بعد أن وضع ابن هشام كتابه.","section":"h1-def","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q03","type":"recall","phase":"practice","prompt":"من هو مؤلف السيرة النبوية المشهورة؟","answer":"أبو محمد عبد الملك بن هشام المعافري (ت 218هـ)","explain":"في جدول «كتب السيرة» أن الكتاب المشهور في هذا الفن هو الذي حرّره ابن هشام المتوفى سنة 218هـ، وهو ليس تأليفًا مستقلًا؛ فقد هذّب فيه كتاب ابن إسحاق. فاجمع في ذهنك ثلاثة أسماء: ابن إسحاق صاحب التأليف الشامل، وابن هشام المهذّب لكتابه، والسهيلي شارحه.","section":"h1-books","checkpoint":"h1-books","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q04","type":"recall","phase":"practice","prompt":"من هو الذي شرح كتاب ابن هشام؟","answer":"أبو القاسم عبد الرحمن السهيلي الأندلسي (ت 581هـ) في الروض الأنف","explain":"قسم «المنهج» وجدول «كتب السيرة» يذكران أن شارح كتاب ابن هشام هو السهيلي الأندلسي في كتاب «الروض الأنف»، وهو شرح موسّع بلغ سبعة مجلدات. فميّز بين صاحب الأصل المهذَّب وبين الشارح الذي فصّل ألفاظه ومعانيه.","section":"h1-books","checkpoint":"h1-books","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q05","type":"recall","phase":"practice","prompt":"من هو أول من صنف في المغازي؟","answer":"عروة بن الزبير رضي الله عنه","explain":"هذه المعلومة مثبتة في قائمة «تحقق من فهمك»: أول من صنف في المغازي هو عروة بن الزبير رضي الله عنه، وقد ورد أيضًا ضمن أشهر المؤلفين في الخريطة الذهنية. فميِّز مرتبته الأولى قبل من جاء بعده، فإن من بعده دوّن وأفرد.","section":"h1-memorize","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q06","type":"recall","phase":"practice","prompt":"من هو أول من دوّن المغازي بترتيب واضح؟","answer":"ابن شهاب الزهري","explain":"في قائمة «تحقق من فهمك» أن ابن شهاب الزهري هو أول من دوّن المغازي بترتيب واضح؛ أي أن دوره جاء في مرحلة تنظيم المادة بعد التصنيف الأول. فتسلسل المعرفة: تصنيف، ثم تدوين مرتّب، ثم تأليف مفرد يخرج للناس.","section":"h1-memorize","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q07","type":"recall","phase":"practice","prompt":"من هو أول من ألف مفرداً وأخرجه للناس في المغازي؟","answer":"موسى بن عقبة","explain":"في القائمة نفسها أن موسى بن عقبة هو أول من أفرد المغازي في مؤلَّف مستقل وأخرجه للناس. وتمييزه عن الزهري أن الزهري دوّن بترتيب، أما موسى بن عقبة فقد جعل لها كتابًا مفردًا أظهره للناس.","section":"h1-memorize","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q08","type":"recall","phase":"practice","prompt":"إلى من ينتهي النسب الشريف باتفاق الأمة؟","answer":"عدنان","explain":"عمود النسب يسرد الأجداد واحدًا واحدًا حتى يبلغ عدنان بن أدد، وعنده يتوقف إجماع الأمة على النسب النبوي؛ فقد نقل الدرس قول عروة بن الزبير: «ما وجدنا من يعرف ما وراء عدنان وقحطان إلا تخرصًا». فاحفظ أن الخلاف يبدأ بعد عدنانية النسب لا قبله.","section":"h1-lineage","checkpoint":"h1-lineage","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q09","type":"recall","phase":"practice","prompt":"من هو أول من جمع قريش وسكنها مكة؟","answer":"قصي بن كلاب","explain":"جدول النسب ينصّ على أن قصي بن كلاب هو أول من جمع قريش وسكنها مكة، وقبل ذلك كانت متفرقة. ولقب «قريش» مشتق من التقرش أي التجمع بعد التفرق كما في المصطلحات؛ فاجمع بين اللقب ومعناه لترسخ الصورة.","section":"h1-lineage","checkpoint":"h1-lineage","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q10","type":"recall","phase":"practice","prompt":"كم اسماً للنبي ﷺ ذكر الجزولي في دلائل الخيرات؟","answer":"200 اسم","explain":"قسم «أسماء النبي ﷺ» يفرّق بين عددي الجزولي وابن دحي: فالجزولي ذكر في «دلائل الخيرات» مئتي اسم، وابن دحي الكلبي في «المستوفى» أوصلها إلى نحو ثلاثمئة، ومصنفات الأسماء تزيد على أربعة عشر. فانتبه إلى أن السؤال عن الجزولي خاصة.","section":"h1-names","checkpoint":"h1-names","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q12","type":"recall","phase":"practice","prompt":"إذا أردت دراسة أخبار الغزوات التي وقعت بعد الهجرة، فأي علم من العلوم التالية أحتاجه؟","answer":"المغازي","explain":"المفتاح في السؤال قيد «بعد الهجرة»؛ فهذا القيد يجعلنا نذهب إلى العلم الذي خُصّ بالغزو والصرايا والبعوث، ونترك السيرة لأنها أعمّ وتشمل العهد المكي والمدني معًا.","section":"h1-def","checkpoint":"h1-def","difficulty":2},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr1-q13","type":"cloze","phase":"practice","prompt":"النسب الشريف للنبي ﷺ ينتهي باتفاق الأمة إلى ______.","answer":"عدنان","explain":"عمود النسب يجعل عدنان آخر ما اتفقت عليه الأمة، وما بينه وبين إسماعيل مختلف فيه: قيل تسعة أو سبعة أو خمسة عشر أو أربعين أبًا. فموضع الفراغ هو هذا الجد لا إبراهيم ولا إسماعيل، لأن الإجماع يتوقف عنده.","section":"h1-lineage","difficulty":3},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مدخل إلى السيرة النبوية ونسب النبي ﷺ","url":"sira/01-lesson/index.html"},{"question":{"id":"sr2-q01","type":"recall","phase":"pretest","prompt":"متى مات عبد الله بن عبد المطلب؟","answer":"قبل مولد النبي ﷺ، وكان جنينًا في بطن أمه","explain":"الخلاصة وقسم «وفاة عبد الله» يوضّحان أن الأب مات والنبي ﷺ بعدُ حملٌ في بطن أمه، ولذلك لم يره ﷺ قط. وقد أرسله عبد المطلب يمتار تمرًا من المدينة فمرض في طريق عودته، فسبقت الوفاةُ الميلادَ.","section":"s2-father","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q02","type":"recall","phase":"pretest","prompt":"كم كان عمر عبد الله عند وفاته؟","answer":"25 سنة","explain":"قسم «وفاة عبد الله» ضبط عمره عند الوفاة بخمس وعشرين سنة، وهو الرقم نفسه المثبت في محور المخطط «وفاة عبد الله: بالمدينة، عمره 25 سنة». فاربط الرقم بالمكان: المدينة ودار النابغة.","section":"s2-father","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q03","type":"recall","phase":"practice","prompt":"أين توفي عبد الله؟","answer":"بالمدينة، في دار النابغة من بني عدي بن النجار","explain":"أرسل عبد المطلب ابنه عبد الله يمتار تمرًا من المدينة، فنزل عند أخواله بني النجار ومرض، ثم توفي في دار النابغة، وهو رجل من بني عدي بن النجار. فموضع الوفاة مدينة وليس مكة، والمكان المحدد دار النابغة.","section":"s2-father","checkpoint":"s2-father","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q04","type":"recall","phase":"practice","prompt":"من هي أمة بنت وهب؟","answer":"أم النبي ﷺ، بنت وهب بن عبد مناف","explain":"قسم «أمة بنت وهب» يعرّفها بأنها والدة النبي ﷺ وابنة وهب بن عبد مناف، وقد تزوجها عبد الله. ولُقّبت «زهرة قريش» لشدّة ذكائها وحسن بيانها، وكانت من أفضل فتيات مكة. فاحفظ نسبها ولقبها معًا.","section":"s2-mother","checkpoint":"s2-mother","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q05","type":"recall","phase":"practice","prompt":"أين تربّت أمة بنت وهب؟","answer":"في بيت عمها وهيب بن عبد مناف","explain":"بطاقة أمة تذكر أن تربيتها كانت في بيت عمها وهيب بن عبد مناف، وأنها من أفضل فتيات مكة؛ تقدّم لخطبتها العشرات وكان والدها يرفض حتى زوّجها عبد المطلب لابنه عبد الله. فميّز بيت العم من بيت الأب.","section":"s2-mother","checkpoint":"s2-mother","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q06","type":"recall","phase":"practice","prompt":"كم كان عمر النبي ﷺ عندما زار قبر أبيه؟","answer":"6 سنوات","explain":"قسم «أمة بنت وهب» ينص على أن الزيارة كانت في السادسة من عمره ﷺ، وقد سافرت معه أمه وأم أيمن إلى المدينة وبكت عند القبر شهرًا كاملًا ثم عادت. فالسؤال عن سنة الزيارة لا عن سنة الوفاة.","section":"s2-mother","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q07","type":"recall","phase":"practice","prompt":"أين توفيت أمة بنت وهب؟","answer":"بالأبواء، بين مكة والمدينة","explain":"بعد انتهاء الزيارة مرضت أمة في الأبواء، وهو موضع بين مكة والمدينة، وهناك توفيت وأم أيمن ترفعها. ففرّق بين القبر الذي زارته في المدينة وبين مكان الوفاة في الأبواء.","section":"s2-death","checkpoint":"s2-death","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q08","type":"recall","phase":"practice","prompt":"من الذي حفر قبر أم النبي ﷺ؟","answer":"النبي ﷺ نفسه بيديه الصغيرتين، مع أم أيمن","explain":"في مشهد الوفاة أن الذي حفر القبر هو النبي ﷺ نفسه بيديه الصغيرتين، وعاونته في ذلك أم أيمن جارية عبد الله، وكان ينظر إلى أمه بخوف ودموع وهو يقول: «أمي، أمي».","section":"s2-death","checkpoint":"s2-death","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q09","type":"recall","phase":"practice","prompt":"من الذي كفله بعد وفاة أمه؟","answer":"جده عبد المطلب بن هاشم","explain":"لما عاد النبي ﷺ إلى مكة توجه إلى بيت جده عبد المطلب، فسأله: «أين أمك؟» فبكى وأخبره أنها ماتت، فضمّه عبد المطلب إليه وقال: «أنت ابني، أنت ابني». فالكفالة بعد الأم آلت إلى الجد.","section":"s2-death","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q10","type":"recall","phase":"practice","prompt":"ما حديث الابتلاء؟","answer":"«أي الناس أشد بلاء؟ الأنبياء ثم الصالحون ثم الأمثل فالأمثل»","explain":"في صندوق «حديث الابتلاء» آخر قسم «وفاة أمه» أن النبي ﷺ سُئل عن أشد الناس بلاءً، فجعل الأنبياء في المقدمة ثم الصالحين ثم يتبع الناس على مراتبهم، ويُبتلى الرجل على قدر دينه. فالمعنى أن شدة الاختبار تتناسب مع قوة الإيمان.","section":"s2-death","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q12","type":"recall","phase":"practice","prompt":"ما أول ما فعله عبد المطلب عندما علم بوفاة أمة؟","answer":"فضمه وقال له: أنت ابني، أنت ابني","explain":"عند عودة النبي ﷺ إلى مكة سأله جده عن أمه، فأخبره بوفاتها وهو يبكي، فأخذه عبد المطلب وضمّه إلى صدره مكررًا أنه ابنه. فهذا المشهد هو أول ما جرى بينهما بعد الوفاة، وبه انتقلت الكفالة إلى الجد.","section":"s2-death","difficulty":2},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr2-q13","type":"cloze","phase":"practice","prompt":"توفي عبد الله بن عبد المطلب وعمره ______ سنة.","answer":"25","explain":"قسم «وفاة عبد الله» والمخطط يجعلان عمر الأب عند الوفاة خمسًا وعشرين سنة؛ فلا تخلطه بعمر النبي ﷺ الذي زار القبر في السادسة، ولا بعمر جده. والوفاة كانت في دار النابغة بالمدينة.","section":"s2-father","checkpoint":"s2-father","difficulty":3},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"مولده ﷺ ويتمه ووفاة أمه","url":"sira/02-lesson/index.html"},{"question":{"id":"sr3-q01","type":"recall","phase":"pretest","prompt":"من الذي أعاد حفر زمزم؟","answer":"عبد المطلب بن هاشم","explain":"قسم «حفر زمزم» يروي أن هاتفًا أتى عبد المطلب في منامه وهو في حجر إسماعيل، فأمره بحفر البئر التي ردمتها جرهم وحدد له مكانها، فتوجه مع ابنه الحارث وحفر حتى ظهر الماء. فهو الذي أعاد اكتشافها وردّها للحياة.","section":"s3-zamzam","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q02","type":"recall","phase":"pretest","prompt":"منذ متى لم تنضب زمزم؟","answer":"منذ 4000 سنة","explain":"عمود «المعجزة» يقول إن البئر لم تجف ولم ينقطع ماؤها منذ إعادة حفرها، وإن الحساب المعتمد في الدرس يرجع أربعة آلاف سنة، مع إشارة إلى أن بعض المصادر تؤرخ مولد إسماعيل عليه السلام بنحو 1910 قبل الميلاد. فالمدة خاصة بماء زمزم بعد إعادة حفره.","section":"s3-zamzam","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q03","type":"recall","phase":"practice","prompt":"ما نذر عبد المطلب؟","answer":"إن رزق الله له عشرة نفر ثم بلغوا معه حتى يمنعوه، ليذبحن أحدهم لله عند الكعبة","explain":"قسم «النذر والفداء» يبيّن أن عبد المطلب علّق نذره على شرط: أن يرزقه الله عددًا من الأبناء يبلغون معه ويمنعونه، فإذا تم ذلك ذبح أحدهم لله عند الكعبة. فلما تحقق الشرط لجأ إلى الاستقسام بالقداح عند هبل.","section":"s3-nadhr","checkpoint":"s3-nadhr","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q04","type":"recall","phase":"practice","prompt":"على من خرج القدح في الاستقسام؟","answer":"على عبد الله، أصغر أبناء عبد المطلب وأحبها إليه","explain":"بطاقة «النتيجة» تذكر أن القدح عند الاستقسام خرج على عبد الله، وكان أصغر أولاد عبد المطلب وأحبهم إلى قلبه، فاشتد الأمر على أبيه. فاحفظ أنه الابن الأصغر والأحب.","section":"s3-nadhr","checkpoint":"s3-nadhr","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q05","type":"recall","phase":"practice","prompt":"كم بلغت الإبل في الفداء؟","answer":"100 بعير","explain":"في بطاقة «العرافة» أن سجاح بخيبر أمرتهم بزيادة الإبل عشرًا عشرًا حتى يرضى الرب، فظل الاستقسام يتكرر حتى بلغت المئة، ثم خرج القدح على الإبل فذبحها عبد المطلب ونجا ابنه.","section":"s3-nadhr","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q06","type":"recall","phase":"practice","prompt":"لماذا يقول النبي ﷺ «أنا ابن الذبيحين»؟","answer":"لأن إسماعيل عليه السلام وعبد الله بن عبد المطلب كلاهما فُدي بذبح","explain":"بطاقة «الذبيحان» تجمع بين إسماعيل عليه السلام الذي فُدي بذبح وعبد الله بن عبد المطلب الذي فُدي بمئة بعير، فصار للنبي ﷺ أبوان نجّاهما الله من الذبح، ولذلك قال: «أنا ابن الذبيحين».","section":"s3-nadhr","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q07","type":"recall","phase":"practice","prompt":"من هو هاشم بن عبد مناف؟","answer":"جد النبي ﷺ، سيد قريش، أول من أطعم الثريد بمكة","explain":"قسم «هاشم بن عبد مناف» يذكر أن اسمه الأصلي عمرو ولُقّب بهاشم لأنه كان يهشم الخبز لقومه، وكان سيد قريش وموسرًا يتولى السقاية والرفادة. وفي سنة القحط جلب الدقيق من فلسطين وصنع الخبز وذبح الذبائح، فكان أول من أطعم الثريد بمكة.","section":"s3-hisham","checkpoint":"s3-hisham","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q08","type":"recall","phase":"practice","prompt":"ما هما الرحلتان اللتان سنّهما هاشم؟","answer":"رحلة الشتاء إلى اليمن ورحلة الصيف إلى الشام","explain":"عمود «الرحلتان» يقسم تجارة قريش على الفصلين: صيفًا تسير شمالًا إلى الشام لبرودة شتائها هناك حتى بصرى والقسطنطينية، وشتاءً تسير جنوبًا نحو اليمن وبلاد الحبشة. فواضع هذا النظام رحلتان متكاملتان لا رحلة واحدة.","section":"s3-ilaf","checkpoint":"s3-ilaf","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q09","type":"recall","phase":"practice","prompt":"ما الإيلاف؟","answer":"اتفاقية تجارية وأمان بين القبائل والدول، فتح أسواق الشام واليمن والحبشة أمام تجار مكة","explain":"قسم «الإيلاف» يشتق الكلمة من الألفة والجمع بعد تفرّق، ويذكر أن قريشًا أخذت عهودًا من الدول المجاورة: فهاشم من ملك الروم، والمطلب من ملوك حمير، ونوفل من كسرى وملوك الحيرة، وعبد الشمس من النجاشي. ومن نتائجه أمن القوافل وفتح الأسواق أمام تجار مكة.","section":"s3-ilaf","checkpoint":"s3-ilaf","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q10","type":"recall","phase":"practice","prompt":"ما سورة قريش؟","answer":"«لِإِيلَافِ قُرَيْشٍ ۝ إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ ۝ فَلْيَعْبُدُوا رَبَّ هَٰذَا الْبَيْتِ ۝ الَّذِي أَطْعَمَهُم مِّن جُوعٍ وَآمَنَهُم مِّنْ خَوْفٍ»","explain":"قسم «الأسواق وسورة قريش» يثبت السورة كاملة، ومطلعها في إيلاف قريش ورحلتي الشتاء والصيف، ثم تنتقل إلى الأمر بعبادة رب البيت الذي أطعمهم من جوع وآمنهم من خوف. فاربط السورة بنعمتي الطعام والأمن لتحفظ ترتيبها.","section":"s3-markets","checkpoint":"s3-markets","difficulty":1},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q12","type":"recall","phase":"practice","prompt":"ما الذي منع عبد المطلب من ذبح ابنه عبد الله مباشرة؟","answer":"قريش منعته وأشاروا عليه باستشارة عرافة","explain":"بطاقة «المنع» تذكر أن أندية قريش قامت إلى عبد المطلب فمنعته من تنفيذ النذر، ثم في بطاقة «الاستشارة» دلّوه على الذهاب إلى الحجاز حيث عرافة لها تابع. فالمؤثر الأول في تأخير الذبح هو منع قريش ورأيهم بالاستشارة.","section":"s3-nadhr","difficulty":2},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"sr3-q13","type":"cloze","phase":"practice","prompt":"الإيلاف: اتفاقية تجارية وأمان بين ______ و______.","answer":"القبائل والدول","explain":"الإيلاف عهد وأمان عقدته قريش مع من حولها، فالعبارة تصف طرفي العهد؛ بدليل توزّع العهود الأربعة على الروم وحمير وكسرى والنجاشي. فاملأ الفراغين بالطرفين اللذين جمع بينهما العهد بعد تفرّق.","section":"s3-ilaf","difficulty":3},"subject":"sira","subjectName":"مادة السيرة النبوية","lessonTitle":"زمزم والإيلاف — هاشم بن عبد مناف","url":"sira/03-lesson/index.html"},{"question":{"id":"hd1-q01","type":"recall","phase":"pretest","prompt":"ما اسم الكتاب الذي سندرسه؟","answer":"الأربعين النووية","explain":"افتح فقرة «الكتاب والمؤلف» تجد أن الكتاب المقرر هو الذي يحمل في وسط عنوانه لفظ «الأربعين»، ويصفه الدرس بأنه يشتمل على 40 حديثًا جمعها الإمام على أصول الدين؛ ولقب «النووية» فيه نسبة إلى مؤلفه، فلا تخلطه بغيره من الأربعينات.","section":"hd1-book","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q02","type":"recall","phase":"pretest","prompt":"من هو مؤلف الأربعين النووية؟","answer":"الإمام محي الدين شرف النووي","explain":"فقرة «الكتاب والمؤلف» تنص على أن جامع هذا الكتاب أحد أئمة الشافعية، وقد سماه الدرس «محي الدين شرف النووي»، ولقب الكتاب نفسه مشتق من اسمه. وميّزه عن ابن دقيق العيد، فالثاني شارح لا مؤلف.","section":"hd1-book","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q03","type":"recall","phase":"practice","prompt":"كم حديثًا في الأربعين النووية؟","answer":"40 حديثًا","explain":"العدد مذكور في أول خلاصة الدرس: «الكتاب يحتوي على 40 حديثًا جمعها الإمام على أصول الدين». ولفظ «الأربعين» في العنوان نفسه إشارة إلى هذا العدد، وتؤكده قائمة «تحقق من فهمك».","section":"hd1-book","checkpoint":"hd1-book","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q04","type":"recall","phase":"practice","prompt":"ما حديث طلب العلم الذي رواه مسلم؟","answer":"«من سلك طريقًا يلتمس به علمًا سهّل الله له به طريقًا إلى الجنة»","explain":"في فقرة «فضائل طلب العلم» يسند الدرس هذا اللفظ إلى صحيح مسلم: «من سلك طريقًا يلتمس به علمًا سهّل الله له به طريقًا إلى الجنة». فلاحظ أن مطلعه «من سلك» لا «من يرد»، فالأخير حديث آخر متفق عليه.","section":"hd1-virtues","checkpoint":"hd1-virtues","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q05","type":"recall","phase":"practice","prompt":"ما حديث «من يرد الله به خيرًا»؟","answer":"«من يرد الله به خيرًا يفقهه في الدين» — متفق عليه","explain":"فقرة «فضائل طلب العلم» تفرّق بين حديثين: أحدهما لمسلم في سلوك الطريق، والآخر متفق عليه في التفقه، ومطلعه «من يرد الله به خيرًا...»، وقد علّق الدرس عليه بأن التفقه في الأحاديث دليل على أن الله أراد بالعبد خيرًا.","section":"hd1-virtues","checkpoint":"hd1-virtues","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q06","type":"recall","phase":"practice","prompt":"ما المحجة البيضاء؟","answer":"جادة الطريق، طريق النبي ﷺ وأصحابه وسلف الأمة","explain":"فقرة «المحجة البيضاء» تشرح حديث: «تركتكم على المحجة البيضاء ليلها كنهارها لا يزيغ عنها إلا هالك»، فتقول إنها جادة الطريق أي طريق النبي ﷺ وأصحابه وسلف الأمة، وإن «ليلها كنهارها» كناية عن وضوحها وانتفاء اللبس فيها.","section":"hd1-path","checkpoint":"hd1-path","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q07","type":"recall","phase":"practice","prompt":"ما فضل الصلاة على النبي ﷺ في هذا العلم؟","answer":"يتصل إسنادك بالنبي ﷺ، وتحيي سنة قراءة الحديث بالسند المتصل، وتنال النظارة","explain":"فقرة «فضل الصلاة على النبي ﷺ» تعدّ ثلاث فوائد: أن الإكثار منها يصل إسنادك بالنبي ﷺ، ويحيي سنة قراءة الحديث على المشايخ بسند متصل، وينيلك النظارة؛ وقد عرّف الدرس «النظارة» بأنها نظارة الوجه الحسن الجميل.","section":"hd1-salawat","checkpoint":"hd1-salawat","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q08","type":"recall","phase":"practice","prompt":"ما حديث النظارة الذي رواه ابن ماجه؟","answer":"«نظر الله امرئ سمع مقاله فبلغها، فرب حامل فقه غير فقيه، ورب حامل فقه إلى من هو أفقه منه»","explain":"تحت محور «النظارة» في فقرة الصلاة على النبي ﷺ يخرّج الدرس حديثًا مطلعه «نظر الله امرئ سمع مقاله فبلغها» وينسبه إلى سنن ابن ماجه، وفي «المصطلحات» أن «رواه ابن ماجه» تعني الإمام ابن ماجه في سننه، فقرينة الراوي تعينك على تمييزه.","section":"hd1-salawat","checkpoint":"hd1-salawat","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q09","type":"recall","phase":"practice","prompt":"ما شروط الأربعين النووية؟","answer":"أكثرها صحيحة، معظمها في البخاري ومسلم، محذوفة الأسانيد ليسهل حفظها","explain":"سطر «الشروط» في فقرة «منهج النووي في الأربعين» يجمع ثلاثة قيود: أن يكون أكثر الحديث صحيحًا، وأن يكون معظمه مخرّجًا في الصحيحين، وأن تُحذف الأسانيد تيسيرًا للحفظ. ولخّصت الخريطة الذهنية القيد الأول والثالث بقولها «صحيحة أو حسنة» و«محذوفة الأسانيد».","section":"hd1-method","checkpoint":"hd1-method","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q10","type":"recall","phase":"practice","prompt":"ما الشرح المعتمد للأربعين النووية؟","answer":"شرح الأربعين النووية لابن دقيق العيد","explain":"في فقرة «منهج النووي في الأربعين» يقع تحت «الشرح» اسم الشارح المعتمد، وهو ابن دقيق العيد، وقد أثبته الدرس أيضًا في الخريطة الذهنية وفي المصطلحات تحت «الكتب والأعلام». وميّزه عن النووي، فالثاني جامع لا شارح.","section":"hd1-method","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q12","type":"recall","phase":"practice","prompt":"ما هي شروط الأربعين النووية التي ذكرها الدرس؟","answer":"أكثرها صحيحة، معظمها في البخاري ومسلم، محذوفة الأسانيد ليسهل حفظها","explain":"نصّ الدرس في «منهج النووي» على ثلاثة شروط تحت عنوان «الشروط»: كثرة الصحة، وكون الأكثر في البخاري ومسلم، وحذف السند رفقًا بالحافظ. فالشرط الأخير ليس ضعفًا بل اختصارًا لخدمة الحافظ.","section":"hd1-method","difficulty":2},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd1-q13","type":"recall","phase":"practice","prompt":"ما المقصود بالمحجة البيضاء في حديث النبي ﷺ؟","answer":"جادة الطريق، طريق النبي ﷺ وأصحابه وسلف الأمة","explain":"فقرة «المحجة البيضاء» تفسّرها بأنها جادة الطريق، أي طريق النبي ﷺ وأصحابه وسلف الأمة، وتستشهد بحديث «ليلها كنهارها لا يزيغ عنها إلا هالك»؛ ومعنى «ليلها كنهارها» أنها لا لبس فيها بل تتضح كالنهار.","section":"hd1-path","checkpoint":"hd1-path","difficulty":3},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"مدخل إلى شرح الأربعين النووية","url":"hadith/01-lesson/index.html"},{"question":{"id":"hd2-q01","type":"recall","phase":"pretest","prompt":"ما أول حديث في الأربعين النووية؟","answer":"«إنما الأعمال بالنيات»","explain":"في فقرة «الحديث والراوي» يقرّر الدرس أن هذا الحديث هو أول ما افتتح به النووي أربعينه، ويصفه بأنه قاعدة عظيمة في الإسلام. ونصّه مثبَت في صدر الدرس مفتتحًا بقوله: «إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى».","section":"hd2-hadith","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q02","type":"recall","phase":"pretest","prompt":"من رواه هذا الحديث؟","answer":"البخاري ومسلم عن عمر بن الخطاب","explain":"تجمع فقرة «الحديث والراوي» بين تسمية الراوي، وهو عمر بن الخطاب رضي الله عنه، وتخريج الحديث في الصحيحين؛ وتقول إن صحيح البخاري ومسلم من أصحّ كتب الحديث. ويؤكد ذلك سطر التخريج أسفل صندوق النص.","section":"hd2-hadith","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q03","type":"recall","phase":"practice","prompt":"ما معنى «إنما»؟","answer":"تفيد الحصر","explain":"في «شرح الحديث» يبيّن الدرس أن «إنما» أداة حصر، فتفيد قصر صحة العمل وكماله على النية؛ أي إن العمل لا يصح ولا يكمل إلا إذا قارنته نية صاحبه.","section":"hd2-meaning","checkpoint":"hd2-meaning","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q04","type":"recall","phase":"practice","prompt":"ما النية شرعًا؟","answer":"اعتقاد القلب فعل الشيء وعزمه عليه من غير تردد","explain":"فقرة «شرح الحديث» تعرّف النية اصطلاحًا بأنها اعتقاد القلب وعزمه على الفعل دون تردد، وتزيد أن التردد غير مشترط وأن وقوعه لا يضر، وقبلها ذكرت معناها اللغوي وهو القصد.","section":"hd2-meaning","checkpoint":"hd2-meaning","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q05","type":"recall","phase":"practice","prompt":"ما المرتبة الأولى من مراتب النية؟","answer":"تمييز العادات عن العبادات","explain":"فقرة «مراتب النية» تعدّ المرتبة الأولى وتوضحها بالمثال: الاستحمام عادة، فإذا نوى به العبد التقرب صار عبادة، وكذلك الأكل والنوم إذا نوى بهما التقوي. فالمعيار نقل الفعل من باب العادة إلى باب العبادة.","section":"hd2-ranks","checkpoint":"hd2-ranks","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q06","type":"recall","phase":"practice","prompt":"ما المرتبة الثانية من مراتب النية؟","answer":"تمييز العبادات بعضها ببعض","explain":"المرتبة الثانية في «مراتب النية» تميّز بين العبادات أنفسها، فيكون الصيام فرضًا أو نفلًا، والصلاة فرضًا أو سنة أو نفلًا؛ فالأولى تميّز العبادة من العادة، والثانية تميّز العبادة من العبادة.","section":"hd2-ranks","checkpoint":"hd2-ranks","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q07","type":"recall","phase":"practice","prompt":"ما المرتبة الثالثة من مراتب النية؟","answer":"الإخلاص","explain":"فقرة «مراتب النية» تجعل الثالثة أعلاها وتسميها الإخلاص، وتفرّع عليها نفي الشرك ونفي الحظ للنفس؛ فبعد تمييز العبادة عن العادة ثم عبادة عن عبادة، جاءت هذه المرتبة لتخليص العمل لوجه الله.","section":"hd2-ranks","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q08","type":"recall","phase":"practice","prompt":"ما الإخلاص؟","answer":"أن يقصد العبد بعمله وجه الله ولا يريد غيره","explain":"في «مراتب النية» يعرّف الدرس الإخلاص بأن يقصد العبد بعمله وجه الله ولا يريد غيره، ويؤكده بقيدين: أن لا يكون في العمل شرك ولا حظ للنفس، وأن لا يكون من أجل فلان أو زيد أو عمرو.","section":"hd2-ranks","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q09","type":"recall","phase":"practice","prompt":"ما سبب ورود حديث النية؟","answer":"رجل هاجر من مكة إلى المدينة ليتزوج امرأة يقال لها أم قيس","explain":"فقرة «سبب ورود الحديث» تحكي أن رجلًا هاجر من مكة إلى المدينة قاصدًا الزواج بامرأة اسمها أم قيس لا ابتغاء وجه الله، فسُمّي بمهاجر أم قيس؛ وسِيق الحديث لبيان أن الأعمال بحسب ما نواه صاحبها.","section":"hd2-cause","checkpoint":"hd2-cause","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q10","type":"recall","phase":"practice","prompt":"ما هي أصول الإسلام الثلاث؟","answer":"حديث عمر «إنما الأعمال بالنيات»، حديث عائشة «من أحدث في أمرنا هذا ما ليس منه فهو رد»، حديث النعمان بن بشير «الحلال بين والحرام بين»","explain":"الخريطة الذهنية تخصص عقدة باسم «الأصول الثلاث» وتعدّ فيها: حديث عمر، وحديث عائشة، وحديث النعمان بن بشير. وحديث النية الذي درسناه هو أول هذه الثلاثة، فاجمعها في هذه العقدة.","section":"hd2-map","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q12","type":"recall","phase":"practice","prompt":"ما المرتبة الأولى من مراتب النية كما ذكرها الدرس؟","answer":"تمييز العادات عن العبادات","explain":"فقرة «مراتب النية» تبدأ بالمرتبة الأولى وتمثل لها بالاستحمام: هو في أصله عادة، فإذا نوى به العبد التقرب صار عبادة؛ وهذا هو تمييز العادات عن العبادات. فالمعيار في النية لا في صورة الفعل.","section":"hd2-ranks","difficulty":2},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd2-q13","type":"recall","phase":"practice","prompt":"ما معنى النية شرعًا كما ورد في الدرس؟","answer":"اعتقاد القلب فعل الشيء وعزمه عليه من غير تردد","explain":"فقرة «شرح الحديث» تفرّق في النية بين معناها لغة وشرعًا: فهي في اللغة القصد، وأما في كلام الفقهاء فهي اعتقاد القلب وعزمه على الفعل دون تردد؛ وقد أضاف الدرس أنها المصرف الذي به يُعرف هل العمل فرض أم لا.","section":"hd2-meaning","difficulty":3},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث النية — إنما الأعمال بالنيات","url":"hadith/02-lesson/index.html"},{"question":{"id":"hd3-q01","type":"recall","phase":"pretest","prompt":"ما اسم الحديث الثاني في الأربعين النووية؟","answer":"حديث جبريل","explain":"فقرة «الحديث والراوي» تسمّي حديث هذا الدرس وتنسبه إلى جبريل عليه السلام، وقد أتى النبي ﷺ في صورة رجل لا يعرفه الصحابة، فلما انصرف قال النبي ﷺ: «هذا جبريل أتاكم يعلّمكم دينكم». وقد عدّه صدر الدرس الحديث الثاني في الأربعين.","section":"hd3-hadith","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q02","type":"recall","phase":"pretest","prompt":"من رواه وعن من؟","answer":"رواه مسلم عن عمر بن الخطاب رضي الله عنه","explain":"فقرة «الحديث والراوي» تنص على أن الإمام مسلمًا أخرجه في صحيحه، وأن راويه عمر بن الخطاب رضي الله عنه، وهو الذي افتتح المتن بقوله: «بينما نحن جلوس عند رسول الله ﷺ ذات يوم إذ طلع علينا رجل»؛ ويؤكده سطر التخريج أسفل النص.","section":"hd3-hadith","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q03","type":"recall","phase":"practice","prompt":"ما مراتب الدين الثلاث؟","answer":"الإسلام والإيمان والإحسان — الثلاثة كلها دين","explain":"فقرة «مراتب الدين الثلاث» تجمع الثلاثة وتقول صراحة إنها كلها دين، فلا يكون الإنسان متدينًا إلا إذا كان مسلمًا قائمًا بأصول الإسلام. وتفصيلها: الأول أصول الإسلام، والثاني الأركان الستة، والثالث المراقبة. وقد ربط الدرس التسمية بأن الدين إسلام وإيمان ومراقبة من الداخل.","section":"hd3-ranks","checkpoint":"hd3-ranks","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q04","type":"recall","phase":"practice","prompt":"كم أركان الإسلام؟ وما هي؟","answer":"خمس: الشهادتان، الصلاة، الزكاة، الصيام، الحج","explain":"فقرة «أركان الإسلام الخمسة» تسوق جواب النبي ﷺ لجبريل حين سأله عن الإسلام، فتعدّ الشهادتين وإقام الصلاة وإيتاء الزكاة وصوم رمضان وحج البيت لمن استطاع؛ وقد أُفردت لها عقدة في الخريطة الذهنية.","section":"hd3-islam","checkpoint":"hd3-islam","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q05","type":"recall","phase":"practice","prompt":"ما الأصناف الثمانية للزكاة؟","answer":"الفقراء والمساكين والعاملين عليها والمؤلفة قلوبهم وفي الرقاب والغارمين وفي سبيل الله وابن السبيل","explain":"تحت محور «الزكاة» في فقرة «الزكاة والصيام والحج» يسمّي الدرس مستحقيها، فيعدّ ثمانية أصناف تختم بابن السبيل، وأعادها في سطر مستقل ضمن المصطلحات. فاحفظها فهي محدودة محصورة.","section":"hd3-worship","checkpoint":"hd3-worship","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q06","type":"recall","phase":"practice","prompt":"ما الصيام في اللغة وفي الشرع؟","answer":"في اللغة: الإمساك والكف عن الشيء — وفي شريعتنا: الإمساك عن الطعام والشراب وشهوتي البطن والفرج","explain":"فقرة «الزكاة والصيام والحج» تفرّق في الصيام بين اللغة والشرع: فهو في اللغة الإمساك والكف عن الشيء، وفي شريعتنا إمساك مخصوص عن الطعام والشراب وشهوتي البطن والفرج؛ ولخّصتها قائمة «تحقق من فهمك» في سطرها الخامس.","section":"hd3-worship","checkpoint":"hd3-worship","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q07","type":"recall","phase":"practice","prompt":"ما قصة زينب امرأة أحمس؟","answer":"حجّت مصمتة (صامتة لا تتكلم)، فقال لها أبو بكر: تكلمي فإن هذا لا يحل، هذا من عمل الجاهلية — والصيام عن الكلام كان في شريعة الأمم السابقة","explain":"فقرة «الزكاة والصيام والحج» تروي عن قيس بن أبي حازم أن أبا بكر دخل على امرأة من أحمس تدعى زينب فوجدها لا تتكلم، فقالت الصحابة إنها حجّت مصمتة، فأمرها أبو بكر بالكلام وبيّن أن السكوت عن الكلام من عمل الجاهلية؛ وهذه الصورة من صيام الأمم السابقة لا من شريعتنا.","section":"hd3-worship","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q08","type":"recall","phase":"practice","prompt":"ما أركان الحج الأربعة؟","answer":"الإحرام، الطواف، السعي، الوقوف بعرفة","explain":"في فقرة «الزكاة والصيام والحج» يذكر الدرس تحت «الحج» أن أركانه أربعة مرتّبة: الإحرام ثم الطواف ثم السعي ثم الوقوف بعرفة، ويقرنها بشرط «إن استطعت إليه سبيلًا» أي القدرة على الوصول مع الأمن على النفس والمال ووجود مؤونة السفر.","section":"hd3-worship","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q09","type":"recall","phase":"practice","prompt":"كم أركان الإيمان؟ وما هي؟","answer":"ستة: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره","explain":"فقرة «أركان الإيمان الستة» تسوق جواب النبي ﷺ عن الإيمان، فتعدّ الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره. وفي تفصيلها أن الإيمان بالرسل يشمل عدم التفريق بينهم وأن أولهم نوح وآخرهم محمد ﷺ.","section":"hd3-iman","checkpoint":"hd3-iman","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q10","type":"recall","phase":"practice","prompt":"ما الإحسان؟","answer":"أن تعبد الله كأنك تراه فإن لم تكن تراه فإنه يراك — وهذه هي المراقبة","explain":"فقرة «الإحسان والمراقبة» تعرّف الإحسان بنص الحديث: «أن تعبد الله كأنك تراه فإن لم تكن تراه إنه يراك»، وتسميه المراقبة؛ وشرحها أن يستحضر العبد أنه بين يدي ربه وأنه مطلع على سره ونيته، فإن غفل عن المشاهدة استمرّ على إحسان العبادة.","section":"hd3-ihsan","checkpoint":"hd3-ihsan","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q11","type":"recall","phase":"practice","prompt":"ما أشراط الساعة الكبرى؟","answer":"نزول عيسى بن مريم، والدجال، ويأجوج ومأجوج، وطلوع الشمس من مغربها","explain":"في فقرة «الساعة وأشراطها» يفرّق الدرس بين أقسام العلامات: قسم مضى، وقسم يتجدد، وقسم لا يأتي إلا بقرب الساعة تمامًا؛ ويسمّي هذا الأخير الأشراط الكبرى، ويعدّ فيه نزول عيسى بن مريم والدجال ويأجوج ومأجوج وطلوع الشمس من مغربها.","section":"hd3-hour","checkpoint":"hd3-hour","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"hd3-q12","type":"recall","phase":"practice","prompt":"ما أشراط الساعة المذكورة في الحديث؟","answer":"أن تلد الأم ربتها، وأن ترى الحفاة العراة العالة رعاء الشاء يتطاولون في البنيان","explain":"صندوق «أشراط الساعة في الحديث» يتوقف عند الصورتين الواردتين في المتن: «أن تلد الأم ربتها»، و«أن ترى الحفاة العراة العالة رعاء الشاء يتطاولون في البنيان»؛ وقد شرحهما بأن البادية تبسط لهم الدنيا فيتباهون في البنيان، وبأن «أماراتها» علاماتها.","section":"hd3-hour","checkpoint":"hd3-hour","difficulty":1},"subject":"hadith","subjectName":"مادة الحديث","lessonTitle":"حديث جبريل — مراتب الدين (الإسلام والإيمان والإحسان)","url":"hadith/03-lesson/index.html"},{"question":{"id":"ak1-q01","type":"recall","phase":"pretest","prompt":"ما اسم الكتاب المقرر في مادة الأخلاق؟","answer":"تذكرة السامع والمتكلم في أدب العالم والمتعلم.","explain":"الدرس يفتح محور «المادة والكتاب» بالتعريف بالمقرر، ويصفه الأستاذ بأنه كتاب متوسط الحجم يجمع آدابًا وأخلاقًا يحتاج إليها طرفان: العالم والمتعلم؛ فحدود موضوعه واضحة من عنوانه ومما وصفه به.","section":"ak1-context","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q02","type":"recall","phase":"pretest","prompt":"من مؤلف الكتاب كما ورد في الدرس؟","answer":"الإمام بدر الدين ابن جماعة الكناني الشافعي.","explain":"بطاقة الخلاصة تنسب الكتاب إلى إمام من أعلام الشافعية، وتورده قائمة «تحقق من فهمك» بلقبه الكامل مع نسبته؛ فلا تخلط بينه وبين مدرّس المادة الذي يشرحه في الجامع.","section":"ak1-memorize","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q03","type":"recall","phase":"practice","prompt":"من مدرّس المادة؟","answer":"الأستاذ محمد جمعة عياد.","explain":"في محور «المادة والكتاب» يقدّم الأستاذ نفسه مدرّسًا للمادة بمشيخة جامع الزيتونة، ويذكر تخرجه من كلية الدراسات الإسلامية والعربية بجامعة الأزهر ثم دراسته العليا في المعهد العالي لأصول الدين؛ وهذه التفاصيل تفيدك في تمييز صاحب الكتاب من شارحه.","section":"ak1-context","checkpoint":"ak1-context","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q04","type":"recall","phase":"practice","prompt":"ما موضوع الكتاب؟","answer":"جملة من آداب العالم والمتعلم وأخلاقهما.","explain":"وصفه الأستاذ بأنه «متوسط الحجم يجمع آدابًا وأخلاقًا يحتاج إليها العالم والمتعلم»؛ فمحور الكتاب علاقة أدبية بين طرفي طلب العلم، ولذلك وضعه الدرس في مقدمة المادة قبل الدخول في مسائلها.","section":"ak1-context","checkpoint":"ak1-context","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q05","type":"recall","phase":"practice","prompt":"كيف تُكتسب الأخلاق بحسب الأستاذ؟","answer":"بكثرة مصاحبة ومرافقة أهل الأدب والأخلاق من العلماء والمشايخ.","explain":"بطاقة «كيف تُكتسب الأخلاق؟» تجعل الطريق إلى الأدب هو الملازمة اليومية لذوي الأدب من العلماء والمشايخ؛ فالمعنى أن الخُلق يُنقل بالمعاشرة والتربية كما تُنقل الصنعة عن أهلها، لا بمجرد الاطلاع على الكتب.","section":"ak1-adab","checkpoint":"ak1-adab","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q06","type":"recall","phase":"practice","prompt":"لماذا كان الفعل أبلغ من القول والقراءة؟","answer":"لأن الأخلاق تظهر في السلوك العملي والقدوة.","explain":"بطاقة «أثر القدوة» تعتمد على أن السلوك يظهر ما لا يظهره الكلام؛ فمن جالس المتأدبين شاهد الأدب واقعًا فحاكاه، ولذلك جُعلت المشاهدة أنفع من الاكتفاء بالقول أو القراءة في تكوين الخلق.","section":"ak1-adab","checkpoint":"ak1-adab","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q07","type":"recall","phase":"practice","prompt":"ما غاية دراسة هذه المادة مع العلوم الشرعية؟","answer":"اكتساب أخلاق النبي ﷺ والتأدب مع تحصيل العلم.","explain":"بطاقة «غاية الطالب» تجمع جناحين: تحصيل العلم الشرعي من جهة، والتخلق بأخلاق النبي ﷺ والعمل بالعلم من جهة أخرى؛ فالمقصود صناعة عالم عامل بأدبه لا حافظ معلومات فقط.","section":"ak1-adab","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q08","type":"recall","phase":"practice","prompt":"ما صورة العالم الذي دعا الأستاذ إلى أن نكون منه؟","answer":"العالم العامل بعلمه والمتأدب بأخلاقه.","explain":"مصطلح «العلماء العاملون» في الدرس يضبط الصورة: أهل علم يترجمون علمهم إلى عمل، ويصفهم الأستاذ بأنها صفة دعا إلى التحلي بها؛ فالتعارض بين العلم والأدب ليس مطلوبًا، والمطلوب الجمع بينهما.","section":"ak1-terms","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q09","type":"recall","phase":"practice","prompt":"ما المرحلة الجامعية التي ذكر الأستاذ أنه تخرج منها بالأزهر؟","answer":"كلية الدراسات الإسلامية والعربية بجامعة الأزهر.","explain":"سرد الأستاذ لنفسه في محور «المادة والكتاب» يتضمن مرحلة تخرجه الجامعي بالأزهر، ثم أشار بعدها إلى دراسته العليا في المعهد العالي لأصول الدين بجامعة الزيتونة؛ فاحفظ ترتيب المرحلتين ولا تخلط بين المؤسستين.","section":"ak1-context","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q10","type":"recall","phase":"practice","prompt":"ما التخصص الذي ذكره الأستاذ في دراساته العليا؟","answer":"ماجستير في الشريعة والقانون بالمعهد العالي لأصول الدين بجامعة الزيتونة.","explain":"تكملة التعريف بالنفس تذكر أن الدراسة العليا كانت في المعهد العالي لأصول الدين بجامعة الزيتونة، وشأنها الجمع بين الجانب الشرعي والقانوني؛ وهو ما يفسر عناية الأستاذ ببعدي العلم والأدب معًا.","section":"ak1-context","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q12","type":"recall","phase":"practice","prompt":"كيف تُكتسب الأخلاق بحسب ما ذكره الأستاذ في الدرس؟","answer":"بكثرة مصاحبة ومرافقة أهل الأدب والأخلاق من العلماء والمشايخ.","explain":"المسألة محورية في الدرس: الأخلاق ثمرة مصاحبة طويلة لأهل الأدب من المشايخ، ولذلك قرنها الأستاذ بالقدوة العملية لا بالإرشاد النظري وحده؛ فكل جواب يقوم على نصيحة منفردة أو كتاب وحده بعيد عن مقصوده.","section":"ak1-adab","difficulty":2},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak1-q13","type":"recall","phase":"practice","prompt":"أكمل الفراغ: غاية طلب العلم هي الجمع بين .............. والتأدب بأخلاق النبي ﷺ.","answer":"العلم الشرعي","explain":"الجملة الثالثة من بطاقة الخلاصة تجمع بين العلم الشرعي والتأدب بأخلاق النبي ﷺ، ثم تختم بأن يكون الطالب من العلماء العاملين؛ فالمعرفة وحدها ناقصة، والأدب بلا علم لا يكفي، والغاية اجتماعهما مع العمل.","section":"ak1-summary","difficulty":2},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مدخل إلى علم الأخلاق وآداب العلم","url":"akhlaq/01-lesson/index.html"},{"question":{"id":"ak2-q01","type":"recall","phase":"pretest","prompt":"ما عنوان كتاب ابن جماعة الذي يدرسه المقرر؟","answer":"تذكرة السامع والمتكلم في أدب العالم والمتعلم.","explain":"في نهاية محور «أبواب الكتاب» يسمّي المصنف كتابه بهذا الاسم الكامل، وهو المقرر الذي يشرحه الأستاذ؛ والعنوان نفسه يفصح عن غرضه من ذكر أدب طرفي العملية: العالم والمتعلم.","section":"ak2-plan","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q02","type":"recall","phase":"pretest","prompt":"ما معنى براعة الاستهلال؟","answer":"أن يذكر المؤلف في مطلع كتابه ما ينبئ عن مقصوده.","explain":"أدرج الدرس هذا المصطلح في قائمة المصطلحات، وربطه بمطلع الكتاب حين بدأ بالبسملة والحمد والصلاة على النبي ﷺ ثم أشار إلى وصفه بالخُلُق العظيم؛ فالمقصود صنعة افتتاحية تلمّح إلى الغرض قبل التصريح به.","section":"ak2-terms","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q03","type":"recall","phase":"practice","prompt":"ما الحاجة التي ذكرها المؤلف سببًا لتصنيف المختصر؟","answer":"حاجة الطلبة إلى معرفة آداب العالم والمتعلم، مع ما قد يمنعهم من السؤال أو ينفّرهم.","explain":"المقدمة تحكي باعث التأليف: حال الطلبة وما يعتريهم من حياء يمنع السؤال أو معاملة تنفّرهم، فصنّف المؤلف مختصرًا يذكّر العالم بواجبه وينبّه الطالب إلى ما يلزمه، ويبيّن ما يشتركان فيه.","section":"ak2-intro","checkpoint":"ak2-intro","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q04","type":"recall","phase":"practice","prompt":"من أين جمع المؤلف مادة كتابه؟","answer":"مما سمعه، وأخذه عن المشايخ، وقرأه في المطالعات، واستفاده في المذاكرات.","explain":"يعدد المؤلف في مقدمته موارد مادته: ما سمعه، ومجالس المشايخ، والمطالعة، والمذاكرة؛ وهذا يدل على أن الكتاب حصيلة مزيج من التلقي الشفهي والقراءة والمراجعة، لا مصدر واحد.","section":"ak2-intro","checkpoint":"ak2-intro","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q05","type":"recall","phase":"practice","prompt":"لماذا حذف المؤلف الأسانيد والأدلة المطولة؟","answer":"كيلا يطول الكتاب على المطالع أو يمله.","explain":"المؤلف أراد مختصرًا مقروءًا لا سفرًا مطوّلًا، فأسقط سلاسل الرواة والأدلة المطولة كي لا يثقل الكتاب على من يطالعه أو يصيبه بالملل؛ والغرض بذلك تربوي عملي لا اختصار للعلم نفسه.","section":"ak2-intro","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q06","type":"recall","phase":"practice","prompt":"كم بابًا في الكتاب؟ اذكر موضوعاتها إجمالًا.","answer":"خمسة: فضل العلم، وآداب العالم، وآداب المتعلم، وآداب صحبة الكتب، وآداب سكن المدارس.","explain":"قرأ الأستاذ من المقدمة ترتيب الكتاب على خمسة أبواب: العلم وأهله، ثم آداب العالم، ثم أدب المتعلم، ثم مصاحبة الكتب، ثم سكن المدارس؛ وهذا التدرج ينتقل من العام إلى الخاص، فاحفظه بهذا النسق.","section":"ak2-plan","checkpoint":"ak2-plan","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q07","type":"recall","phase":"practice","prompt":"ما موضوع الباب الأول؟","answer":"فضل العلم والعلماء وفضل تعليمه وتعلمه.","explain":"محور «الباب الأول: فضل العلم وأهله» يفتح المبحث الأول من الكتاب، وفيه آيات وأحاديث في شرف العلم وأهله وفي الحث على تعليمه وتعلمه؛ فهو مدخل بين يدي آداب العالم والمتعلم.","section":"ak2-merit","checkpoint":"ak2-merit","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q08","type":"recall","phase":"practice","prompt":"بماذا فسّر الأستاذ التفقه في حديث «من يرد الله به خيرًا»؟","answer":"بالتوفيق إلى طلب العلم ومجالسة العلماء والتعلم في الدين.","explain":"تحت «معانٍ شرحها الأستاذ» فُسّر التفقه في هذا الحديث بأنه توفيق يهيئ العبد لطلب العلم ومجالسة العلماء والتعلم في الدين؛ فالتفقه يُقرأ على أنه علامة على أن الله أراد بالعبد خيرًا.","section":"ak2-merit","checkpoint":"ak2-merit","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q09","type":"recall","phase":"practice","prompt":"ما الوصف الذي ذكره الدرس للعلماء في حديث مشهور؟","answer":"أنهم ورثة الأنبياء.","explain":"قبل الحديث في محور الباب الأول وُصف أهل العلم بحمل ميراث النبوة العلمي، فهم قدوة للناس في أقوالهم وأفعالهم وأحوالهم؛ ومن هنا تنشأ مسؤوليتهم في التعليم والاقتداء والعمل بما علموا.","section":"ak2-merit","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q10","type":"recall","phase":"practice","prompt":"ما بعض المعاني التي ذكرها الأستاذ لوضع الملائكة أجنحتها لطالب العلم؟","answer":"التواضع لطالب العلم، أو حضور مجلسه، أو توقيره، أو إعانته على بلوغ مقصده.","explain":"عرض الأستاذ في شرح الحديث وجوهًا محتملة كلها ترجع إلى تعظيم شأن طالب العلم: إما تواضع الملائكة له، أو شهودها مجالس الطلب، أو إجلالها له، أو إعانتها إياه على نيل مطلبه؛ فيُفهم الحديث على التكريم لا على صورة واحدة ملزمة.","section":"ak2-merit","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q11","type":"recall","phase":"practice","prompt":"ما الصلة التي أبرزها الدرس بين العلم والأخلاق؟","answer":"أن أهل العلم قدوة، وأن العلم ينبغي أن يقترن بالأدب والعمل والخشية.","explain":"بطاقات الباب الأول تقرن العلم بخشية الله، وبكون أهله قدوة؛ فالآيات المذكورة ترفع أهل العلم وتربط رفعتهم بخشيتهم، والمقصود أن يظهر أثر العلم في الأدب والعمل حتى ينتفع به الناس.","section":"ak2-merit","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak2-q12","type":"recall","phase":"practice","prompt":"ما الأثر المنقول عن ملازمة ابن القاسم للإمام مالك؟","answer":"ذكر أنه صحبه عشرين سنة، تعلّم الأدب في معظمها والعلم في سنتين، بحسب ما أورده الأستاذ.","explain":"في حواشي المقدمة أثر عن ابن القاسم يفيد أن معظم عشرين سنة من ملازمته للإمام مالك كانت في تعلم الهيئة والسلوك، لا في أخذ المسائل فقط؛ وهو شاهد على أن الأدب جزء أصيل من التلقي عند السلف.","section":"ak2-intro","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"مقدمة الكتاب وفضل العلم والعلماء","url":"akhlaq/02-lesson/index.html"},{"question":{"id":"ak3-q01","type":"recall","phase":"pretest","prompt":"من العلماء الذين تشملهم فضائل العلم بحسب افتتاح الفصل؟","answer":"العلماء العاملون الأبرار المتقون الذين يقصدون وجه الله.","explain":"افتتاح الفصل يقيّد فضائل العلم بقوم موصوفين بثلاث صفات: العمل بالعلم، والبر، والتقوى، مع قصد وجه الله؛ فالمقصود من يقترن علمه بالعمل والصلاح، لا كل من انتسب إلى العلم.","section":"ak3-intention","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q02","type":"recall","phase":"pretest","prompt":"ما النيات التي حذّر الدرس منها في طلب العلم؟","answer":"المراء، ومكاثرة العلماء، وجذب أنظار الناس، وطلب الجاه أو المال أو الشهرة.","explain":"بطاقة «مقاصد حذّر منها الدرس» تجمع أنواع طلب الجاه: الرياء والعجب والتكبر، وطلب المنزلة والمال والشهرة والتصدر؛ وربط الدرس الوعيد بمن طلب العلم ليُقال عنه عالم أو قارئ، فالمحذور في فساد القصد لا في العلم.","section":"ak3-intention","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q03","type":"recall","phase":"practice","prompt":"ما النية التي دعا الأستاذ إلى تجديدها؟","answer":"طلب العلم ابتغاء مرضاة الله ورفع الجهل عن النفس.","explain":"ختم الأستاذ المبحث بدعوة صريحة إلى تصحيح القصد: أن يكون الباعث مرضاة الله من جهة، وإزالة الجهل عن النفس من جهة أخرى؛ فالأولى تتعلق بمن يُطلب له العمل، والثانية بثمرته العلمية.","section":"ak3-intention","checkpoint":"ak3-intention","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q04","type":"recall","phase":"practice","prompt":"ما أول أدب ذكره المؤلف للعالم في نفسه؟","answer":"دوام مراقبة الله تعالى في السر والعلانية.","explain":"تفتح قائمة الآداب السبعة بهذا الأدب، وهو استحضار اطلاع الله على العبد في السر والعلانية كما ورد في المصطلحات؛ وجُعل أولًا لأنه أصل يصحح ما بعده من صيانة العلم والزهد وتنزيه القصد.","section":"ak3-conduct","checkpoint":"ak3-conduct","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q05","type":"recall","phase":"practice","prompt":"متى يجوز للعالم الذهاب إلى المتعلم بدل مجيء المتعلم إليه؟","answer":"عند ضرورة أو حاجة أو مصلحة دينية راجحة، مع حسن النية وانتفاء مفسدة إذلال العلم.","explain":"بيّن المؤلف في أدبه الثاني الحد الذي تصان به مكانة العلم: ألا يبتذله العالم بالذهاب إلى أهل الدنيا بلا باعث؛ فإذا قامت حاجة أو ضرورة أو مصلحة شرعية راجحة جاز ذلك، بشرط سلامة النية وألا يُنزل العلم منزلة يُذلّه.","section":"ak3-conduct","checkpoint":"ak3-conduct","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q06","type":"recall","phase":"practice","prompt":"ما معنى الزهد في الدنيا كما شرحه الأستاذ؟","answer":"زهد القلب وعدم تعلقه بالدنيا، لا لزوم مظهر الفقر أو ترك المباحات.","explain":"الأدب الثالث يحرر محل الزهد بأنه في القلب لا في المظهر، ويفسره الدرس بعدم تعلق النفس بالدنيا؛ ويبقى الاعتدال في النفقة مطلوبًا، فلا يلزم من الزهد إظهار الفقر ولا ترك اللباس الحسن ولا الحرمان من المباح.","section":"ak3-conduct","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q07","type":"recall","phase":"practice","prompt":"ما الأغراض التي لا ينبغي أن يجعل العلم وسيلة إليها؟","answer":"الجاه والمال والسمعة والشهرة والخدمة والتقدم على الأقران.","explain":"الأدب الرابع يسميه «تنزيه العلم عن الأغراض»، فيمنع أن يكون العلم سُلمًا للمنافع: المنزلة، أو المال، أو الشهرة، أو التقدم على الأقران؛ ويزيد منع استغلال الطلبة بالخدمة أو المال بسبب تعلمهم عليه.","section":"ak3-conduct","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q08","type":"recall","phase":"practice","prompt":"ما المقصود باجتناب مواضع التهمة؟","answer":"الابتعاد عما يوقع الناس في سوء الظن أو يقدح في المروءة، ولو كان الفعل جائزًا في أصله.","explain":"الأدب الخامس يضمّ أمرين: طهارة المكاسب مما عده المؤلف دنيئًا أو مكروهًا في عرفه وشرعه، والبعد عما يجلب الظنون السيئة؛ وقد نبّهت المصطلحات إلى أن الفعل قد يكون جائزًا في أصله لكنه يُتجنّب سدًّا لباب قالة السوء.","section":"ak3-conduct","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q09","type":"recall","phase":"practice","prompt":"ما الشعائر التي يحافظ عليها العالم؟","answer":"شعائر الإسلام وظواهر أحكامه، بامتثال المأمورات واجتناب المنهيات.","explain":"الأدب السادس يعنى بموافقة الظاهر للسان: فيؤدي العالم المأمورات وينتهي عن المنهيات لتكون دعوته موافقة لحاله، فلا تناقض بين ما يدعو إليه الناس وما يفعله هو.","section":"ak3-conduct","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q10","type":"recall","phase":"practice","prompt":"ما أمثلة المندوبات التي ذكرها الأستاذ؟","answer":"قيام الليل، وقراءة القرآن، والذكر، والتذكير، والصدقة.","explain":"الأدب السابع يجعل النوافل ميدانًا يقتدي فيه الطالب بعالمه، ومثّل لها بأعمال متنوعة بين قولية وفعلية: قيام الليل وقراءة القرآن والذكر والصدقة؛ فالمقصود الإكثار من الطاعة لا الاكتفاء بالفرائض.","section":"ak3-conduct","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q11","type":"recall","phase":"practice","prompt":"لماذا يحافظ العالم على النوافل بحسب الدرس؟","answer":"ليكون قدوة وأسوة للناس في العبادة والسلوك.","explain":"العالم مطالب بأن يكون قدوة في العلم، وكذلك في العبادة؛ ولذلك حثّه الدرس على المندوبات لتظهر آثار الطاعة في سلوكه، فيقتدي به طلبته والناس في الإقبال على العبادة والطاعة.","section":"ak3-conduct","difficulty":1},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"ak3-q13","type":"recall","phase":"practice","prompt":"كم عدد آداب العالم في نفسه التي ذكرها الدرس؟","answer":"سبع آداب.","explain":"لخصت الخلاصة القائمة في سبعة أنواع تجمع حق الله وحق النفس وحق العلم: المراقبة، وصيانة العلم، والزهد، وتنزيه العلم عن الأغراض، ونزاهة المكاسب، وشعائر الإسلام، والمندوبات؛ وعلى هذا التقسيم بنى الأستاذ شرح الباب.","section":"ak3-conduct","difficulty":2},"subject":"akhlaq","subjectName":"مادة الأخلاق","lessonTitle":"إخلاص النية وآداب العالم في نفسه","url":"akhlaq/03-lesson/index.html"},{"question":{"id":"nh1-q01","type":"recall","phase":"pretest","prompt":"ما الكتاب الذي اختاره الأستاذ للمادة؟","answer":"كتاب «الدروس النحوية»، والدرس يخص الجزء الثاني منه.","explain":"تجد هذا في مطلع قسم «المادة والكتاب»: الكتاب المعتمد هو «الدروس النحوية»، وهو مبسط ومناسب للمبتدئ، ويُدرَّس منه في هذه المادة جزؤه الثاني.","section":"nh1-intro","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q02","type":"recall","phase":"pretest","prompt":"كيف وصف الأستاذ الكتاب؟","answer":"وصفه بأنه شيق ومبسط، ويحوي معلومات قيمة وضرورية للمبتدئ.","explain":"في القسم نفسه وُصف الكتاب بأنه مبسط ومناسب للمبتدئ، وأن علماء في اللغة العربية اشتركوا في تأليفه؛ فهو كتاب تعليمي أولي لا يطلب من الطالب فيه مقدمات عالية.","section":"nh1-intro","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q03","type":"recall","phase":"practice","prompt":"كيف قُسم تدريس الجزء الثاني من الكتاب؟","answer":"إلى جزأين: الأول في السداسي الأول والثاني في السداسي الثاني.","explain":"ذكر قسم «المادة والكتاب» أن هذا المقرر يخص الجزء الثاني، وأنه موزع على جزأين خلال السداسيين؛ فيأخذ الطالب جزءًا من الكتاب في الفصل الأول وجزءًا في الثاني.","section":"nh1-intro","checkpoint":"nh1-intro","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q04","type":"recall","phase":"practice","prompt":"ما أقسام الكلام التي ذكرها في خطة المقرر؟","answer":"الاسم والفعل والحرف.","explain":"المحور الأول في جدول الخطة عنوانه «مدخل الكلام»، وفيه تُعد أنواع الكلمة ثلاثة، ثم ينتقل الباب بعدها إلى دراسة الحروف؛ فهذه الأنواع هي مدخلك إلى بقية الأبواب.","section":"nh1-plan","checkpoint":"nh1-plan","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q05","type":"recall","phase":"practice","prompt":"بأي اعتبار يقسم الدرس الأفعال أولًا؟","answer":"بحسب الزمن إلى ماضٍ وحاضر أو مستقبل.","explain":"في صف «الأفعال» من جدول الخطة أن أول اعتبار للتقسيم عنده هو الزمن؛ فيقسم الفعل بحسبه إلى ماضٍ وما هو حاضر أو مستقبل، ثم تأتي بعده اعتبارات آخر الفعل والإعراب.","section":"nh1-plan","checkpoint":"nh1-plan","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q06","type":"recall","phase":"practice","prompt":"ما التقسيم الآخر للأفعال الذي ذكره؟","answer":"صحيحة الآخر ومعتلة الآخر، ثم معربة ومبنية.","explain":"الاعتبار الثاني للأفعال في الخطة يرجع إلى آخر الكلمة: صحيح الآخر ومعتله، ثم المعرب والمبني؛ وبه يُضاف إلى تقسيم الزمن وجه آخر للتصنيف.","section":"nh1-plan","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q07","type":"recall","phase":"practice","prompt":"ما العوامل التي ستدرس في باب الأفعال؟","answer":"عوامل الرفع والنصب والجزم، وذكر الأستاذ أن الرفع يكون لعدم وجود ناصب أو جازم.","explain":"أفردت الخطة للأفعال عوامل ثلاثة: الرفع والنصب والجزم. والضابط الذي أشار إليه الأستاذ أن الفعل يبقى مرفوعًا ما لم يسبقه ناصب أو جازم؛ فالرفع هو الأصل وما عداه يحتاج إلى عامل.","section":"nh1-plan","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q08","type":"recall","phase":"practice","prompt":"اذكر ثلاثة من تقسيمات الأسماء المعلنة.","answer":"مثل: صحيحة الآخر ومعتلة الآخر، نكرة ومعرفة، مفرد ومثنى وجمع، مذكر ومؤنث، منون وغير منون.","explain":"عرض محور «الأسماء» في الخطة أوجهًا متعددة للتصنيف: من جهة آخر الكلمة صحيح ومعتل، ومن جهة التعريف نكرة ومعرفة، ومن جهة العدد مفرد ومثنى وجمع، ومن جهة النوع مذكر ومؤنث، ومن جهة التنوين منون وغير منون.","section":"nh1-plan","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q09","type":"recall","phase":"practice","prompt":"لماذا تُعد العربية والنحو من علوم الآلة؟","answer":"لأنها وسائل لفهم كلام الله وكلام النبي ﷺ.","explain":"بطاقة «فهم النصوص» تجعل النحو وسيلة لا غاية: فهو من علوم الآلة التي يحتاج إليها طالب العلم ليصل بها إلى المقصود، وهو فهم القرآن الكريم والحديث النبوي؛ فقيمته في كونه قنطرة إلى النصوص.","section":"nh1-purpose","checkpoint":"nh1-purpose","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q10","type":"recall","phase":"practice","prompt":"ما الغاية من وضع قواعد النحو بحسب عرض الأستاذ؟","answer":"حفظ العربية من اللحن والتحريف والاندثار، وإعانة المتعلم على فهم النصوص.","explain":"بطاقة «صيانة العربية» تربط وضع القواعد بالحفاظ على اللسان من الخطأ في الاستعمال ومن التحريف، مع إعانة المتعلم على فهم النصوص؛ فالغايتان معًا: حفظ اللغة وخدمة الفهم.","section":"nh1-purpose","checkpoint":"nh1-purpose","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q11","type":"recall","phase":"practice","prompt":"من الذي ذكره الأستاذ في سياق وضع قواعد النحو؟","answer":"ذكر عليًا رضي الله عنه وأبا الأسود الدؤلي.","explain":"أوردت بطاقة «صيانة العربية» أن الدعوة إلى تدوين قواعد النحو نشأت في عهد علي رضي الله عنه، وذُكر في هذا السياق أبو الأسود الدؤلي؛ فهو من أعلام الرواية في نشأة النحو.","section":"nh1-purpose","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh1-q13","type":"recall","phase":"practice","prompt":"أي العبارات التالية تلخص غاية علم النحو كما عرضها الأستاذ في الدرس؟","answer":"النحو من علوم الآلة التي تعين على فهم القرآن والحديث وصيانة العربية من اللحن والتحريف والاندثار.","explain":"اجمع بطاقات قسم «غاية علم النحو»: فالبطاقة الأولى تربط النحو بفهم القرآن الكريم والحديث النبوي، والثانية تصون اللسان من اللحن والتحريف، والثالثة تضم إليه الصرف والبلاغة واللغة. والعبارة الجامعة هي التي تستوعب هذه الوجوه كلها.","section":"nh1-purpose","difficulty":2},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"مدخل إلى علم النحو وبرنامج المادة","url":"nahw/01-lesson/index.html"},{"question":{"id":"nh2-q01","type":"recall","phase":"pretest","prompt":"إلى ماذا يوجّه علم النحو بحثه في الألفاظ؟","answer":"إلى اللفظة بعد تركيبها مع غيرها بما يؤدي إلى فائدة يحسن السكوت عليها.","explain":"بطاقة «اللفظة في التركيب» في قسم ما يدرسه النحو تبين أن النظر النحوي ينتقل من الكلمة وحدها إلى حال اتصالها بغيرها، فيصير الكلام مفيدًا ويحسن السكوت عليه.","section":"nh2-word","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q02","type":"recall","phase":"pretest","prompt":"ما المجال الذي يبحث في اللفظة المفردة ومعناها؟","answer":"علم اللغة والمعاجم، بحسب شرح الأستاذ.","explain":"بطاقة «اللفظة المفردة» تنسب البحث في معنى اللفظ منفردًا إلى علم اللغة والمعاجم؛ ومثال الدرس أن معنى «كتاب» يُعرف من الحصيلة اللغوية قبل النظر في موقعه من التركيب.","section":"nh2-word","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q03","type":"recall","phase":"practice","prompt":"ما أقسام الكلمة الثلاثة؟","answer":"الاسم والفعل والحرف.","explain":"في قسم الأقسام الثلاثة يظهر أن لكل كلمة موضعًا في واحد من ثلاثة أنواع؛ وضابط التمييز المعروض أن تسأل عن الزمن ثم تصنف. والخريطة الذهنية تجعل هذه الأنواع فروعًا للكلمة.","section":"nh2-classes","checkpoint":"nh2-classes","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q04","type":"recall","phase":"practice","prompt":"عرّف الفعل بحسب الدرس.","answer":"ما يدل على معنى مستقل بالفهم، والزمن جزء من دلالته.","explain":"الجدول يبين أن الفعل يفهم معناه دون حاجة في أصله إلى لفظ آخر، لكن مزية دلالته أن الزمن داخل فيها؛ فمثال «خرج» حدث مقترن بزمن مضى.","section":"nh2-classes","checkpoint":"nh2-classes","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q05","type":"recall","phase":"practice","prompt":"ما معيار الأستاذ للتفريق بين الماضي والحاضر والمستقبل؟","answer":"وقت التكلم: ما قبله ماضٍ، وما يقع فيه حاضر، وما بعده مستقبل.","explain":"جعل الأستاذ «وقت التكلم» قطب القياس، وهو لحظة النطق؛ فما سبق هذه اللحظة فماضٍ، وما يجري فيها فحاضر، وما يليها فمستقبل. فالمقياس زمني نسبي إلى المتكلم.","section":"nh2-classes","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q06","type":"recall","phase":"practice","prompt":"ما أمثلة الماضي والمضارع والأمر التي ذكرها؟","answer":"خرج، ويخرج، واخرج.","explain":"من صف الفعل في الجدول: «خرج» صور حدثًا انقضى، و«يخرج» دل على ما يجري أو سيقع، و«اخرج» طلب من المخاطب وقوع الفعل بعد لحظة الكلام.","section":"nh2-classes","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q07","type":"recall","phase":"practice","prompt":"عرّف الاسم كما ورد في الدرس.","answer":"ما يدل على معنى مستقل بالفهم، وليس الزمن جزءًا من دلالته.","explain":"الاسم في الجدول يفهم معناه دون حاجة إلى غيره، لكنه لا يخبر بذاته عن زمن وقوع شيء؛ فإذا لفظت «كتاب» أدركت المسمى ولم تحمل معه فكرة المضي أو الاستقبال.","section":"nh2-classes","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q08","type":"recall","phase":"practice","prompt":"ما أمثلة الأسماء التي ساقها الأستاذ؟","answer":"زيد، ومسلم، وكتاب، وقلم.","explain":"مثال أعلام وأجناس في قسم الأقسام: «زيد» و«مسلم» من الأعلام، و«كتاب» و«قلم» من الأسماء العامة، وكلها تدل على معنى مستقل دون أن يكون الزمن جزءًا منه.","section":"nh2-classes","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q09","type":"recall","phase":"practice","prompt":"لماذا لا يستقل الحرف بالفهم بحسب الشرح؟","answer":"لأن معناه يحتاج إلى متعلق من اسم أو فعل حتى يتضح.","explain":"الحرف في الجدول يحمل معنى لا ينكشف إلا إذا وجد ما يتعلق به؛ فوجوده مع الفعل أو الاسم هو الذي يوضح المراد منه، ومن غير متعلق يبقى معناه مبهمًا.","section":"nh2-classes","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q10","type":"recall","phase":"practice","prompt":"كيف يظهر معنى النفي في مثال «لم»؟","answer":"يتعلق بالفعل، مثل: «لم يخرج زيد»، فيتوجه النفي إلى الخروج.","explain":"مثال الدرس «لم يخرج» يبين أن الحرف إذا اتصل بالفعل تكشّف المراد؛ فقد توجه النفي إلى حدث الخروج نفسه. فبدون الفعل لا يعرف السامع ما الذي تريد نفيه.","section":"nh2-classes","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q11","type":"recall","phase":"practice","prompt":"ما المثالان اللذان يوضحان تعلق الحرف بالاسم؟","answer":"«بسم الله» و«الكتاب على الطاولة».","explain":"في صف الحرف من الجدول مثالان يتعلق فيهما الحرف بالاسم: الباء في «بسم الله» تُظهر معناها مع ما بعدها، و«على» تتضح دلالتها مع «الطاولة».","section":"nh2-classes","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh2-q13","type":"recall","phase":"practice","prompt":"ما الفرق الذي يذكره الدرس بين دلالة الاسم ودلالة الفعل؟","answer":"الفعل يدل على معنى مستقل بالفهم ويكون الزمن جزءًا من دلالته، أما الاسم فيدل على معنى مستقل من غير أن يكون الزمن جزءًا من معناه.","explain":"أنسب طريقة للتفريق هي سؤال الجدول: هل الزمن داخل في المعنى نفسه؟ فقولنا «خرج» يحمل الحدث وزمنه معًا، أما «كتاب» فيحمل المسمى فقط دون أن يحدد متى وقع شيء. فعلامة الفرق إذن حضور الزمن أو غيابه.","section":"nh2-classes","difficulty":2},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"أقسام الكلمة: اسم وفعل وحرف","url":"nahw/02-lesson/index.html"},{"question":{"id":"nh3-q01","type":"recall","phase":"pretest","prompt":"ما الفرق بين حروف المباني وحروف المعاني؟","answer":"حروف المباني تُركّب لتكوين الكلمات، أما حروف المعاني فتدل على معانٍ في الاستعمال، وقد تعمل في غيرها.","explain":"الجدول في قسم الفرق بين النوعين يقابل بين وظيفتين: حروف النوع الأول تدخل في صورة الكلمة نفسها كالكاف والتاء والباء في «كتب»، وحروف النوع الثاني تضيف معنى عند استعمالها مع غيرها وقد تعمل في إعراب ما بعدها.","section":"nh3-distinction","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q02","type":"recall","phase":"pretest","prompt":"كم عدد حروف الأبجدية الذي ذكره الأستاذ؟","answer":"ثمانية وعشرون حرفًا.","explain":"في مربع «مفتاح التذكر» أن عدد حروف الأبجدية 28، وذكر إلى جانبها أن حروف المعاني تقارب 80؛ فالأولى حروف بناء، والثانية أدوات دلالة.","section":"nh3-distinction","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q03","type":"recall","phase":"practice","prompt":"إلى كم مجموعة رتّب الأستاذ حروف المعاني بحسب تركيبها؟","answer":"إلى خمس مجموعات: أحادية وثنائية وثلاثية ورباعية وخماسية.","explain":"جدول أمثلة حروف المعاني مرتب على خمسة صفوف بحسب عدد أجزاء الحرف: يبدأ بالأحادي كالباء والسين، وينتهي بالخماسي كـ«لكن» و«إنما»، وبينهما الثنائي والثلاثي والرباعي.","section":"nh3-groups","checkpoint":"nh3-groups","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q04","type":"recall","phase":"practice","prompt":"ما معنى الباء في مثال «بسم الله» بحسب الدرس؟","answer":"من معانيها الاستعانة، وتجر ما بعدها في المثال.","explain":"صف الباء في جدول الأمثلة يذكر معناها وأثرها معًا: فهي في «بسم الله» تفيد الاستعانة، وتعمل في الاسم بعدها بالجر؛ ولهذا عُدّت من الحروف العاملة.","section":"nh3-groups","checkpoint":"nh3-groups","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q05","type":"recall","phase":"practice","prompt":"ما دلالة الواو والتاء في «والله» و«تالله»؟","answer":"القسم.","explain":"أورد الدرس صيغتي القسم «والله» و«تالله»، وجعل الواو والتاء أداتي هذا المعنى؛ وبهما يظهر أن الحرف المفرد قد يؤدي دلالة خاصة عند تركيبه.","section":"nh3-groups","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q06","type":"recall","phase":"practice","prompt":"ما دلالة السين في «سأكتب»؟","answer":"الاستقبال القريب بحسب شرح الأستاذ.","explain":"السين في جدول الأمثلة تدخل على الفعل فتفيد أن الحدث يقع بعد لحظة الكلام على القرب؛ ومثلها في الدرس «سأكتب».","section":"nh3-groups","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q07","type":"recall","phase":"practice","prompt":"ما الفرق الذي ذكره الأستاذ بين الفاء وثم في العطف؟","answer":"الفاء للترتيب، وثم للترتيب مع التراخي.","explain":"الحرفان يشتركان في العطف، ويفترقان في مقدار الفاصل بين الحدثين: الفاء تفيد الترتيب، و«ثم» تزيد عليه التراخي، أي وجود مهلة أو فاصل بين الحدثين.","section":"nh3-groups","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q08","type":"recall","phase":"practice","prompt":"ما دلالة «لم» كما وصفها المحاضر؟","answer":"حرف نفي وجزم وقلب.","explain":"وردت «لم» في المجموعة الثنائية، ونسب إليها في صفها ثلاث وظائف مجتمعة: النفي والجزم والقلب؛ ومثلها في الدرس «لم يخرج».","section":"nh3-groups","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q09","type":"recall","phase":"practice","prompt":"ما دلالة «ليت» و«لعل» في أمثلة الدرس؟","answer":"ليت للتمني، ولعل للترجي.","explain":"«ليت» في المجموعة الثلاثية ومعناها التمني، و«لعل» في المجموعة الرباعية ومعناها الترجي؛ فترتيب الجدول يعينك على ربط كل حرف بمعناه.","section":"nh3-groups","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q10","type":"recall","phase":"practice","prompt":"ما المعنيان اللذان ذكرهما الأستاذ لحرف «إلا»؟","answer":"الاستثناء والحصر.","explain":"«إلا» في المجموعة الرباعية، وقد أثبت لها الدرس معنيين لا معنى واحدًا؛ فدلالتها تتحدد من التركيب الذي جاءت فيه، بخلاف ما يُلزم بمعنى واحد كالسين للاستقبال.","section":"nh3-groups","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q11","type":"recall","phase":"practice","prompt":"ما دلالة «لكن» و«إنما»؟","answer":"لكن للاستدراك، وإنما للحصر.","explain":"«لكن» و«إنما» هما حرفا المجموعة الخماسية، ولكل منهما أثر في فهم الجملة: فالأول يستدرك فيعدل الحكم السابق، والثاني يقصر المعنى على ما ذُكر في السياق، والمثال الشاهد «إنما إلهكم إله واحد».","section":"nh3-groups","difficulty":1},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"},{"question":{"id":"nh3-q13","type":"recall","phase":"practice","prompt":"كيف تفرق بين حروف المباني وحروف المعاني بحسب ما ذكره الأستاذ؟","answer":"حروف المباني تُركّب لتكوين صورة الكلمة ولا يقصد بها معنى مستقل في التركيب، أما حروف المعاني فتضيف معنى عند استعمالها مع غيرها وقد تؤثر في إعراب ما بعدها.","explain":"مفتاح التمييز أن تسأل عن وظيفة الحرف: فالكاف والتاء والباء في «كتب» تدخل في بناء اللفظ ولا تحمل معنى مستقلًا، أما الباء في «بسم الله» فتضيف الاستعانة وتجر ما بعدها، والسين في «سأكتب» تدل على الاستقبال؛ فالأولى مبانٍ والثانية معانٍ.","section":"nh3-distinction","checkpoint":"nh3-distinction","difficulty":2},"subject":"nahw","subjectName":"مادة النحو","lessonTitle":"حروف المباني وحروف المعاني","url":"nahw/03-lesson/index.html"}];
